window.KHKT_DATA = {"10":[{"id":"10-II","so":"II","ten":"Bất phương trình và hệ bất phương trình bậc nhất hai ẩn","hk":1,"lessons":[{"id":"10-II-3","ten":"Bài 3. Bất phương trình bậc nhất hai ẩn","ycc":["Nhận biết bất phương trình bậc nhất hai ẩn, nghiệm và miền nghiệm.","Biểu diễn miền nghiệm trên mặt phẳng tọa độ; vận dụng vào bài toán thực tế."],"kt":["Dạng ax + by < c (hoặc ≤, >, ≥), với a, b không đồng thời bằng 0.","Miền nghiệm là một nửa mặt phẳng có bờ là đường thẳng ax + by = c.","Cách xác định: vẽ đường bờ, lấy một điểm không nằm trên bờ (thường là O) thay vào để chọn nửa mặt phẳng.","Với dấu ≤ hoặc ≥ thì miền nghiệm gồm cả đường bờ."],"d":{"t":"mc","q":"Cặp số nào là một nghiệm của bất phương trình 2x − y > 3?","o":["(1; 1)","(0; −3)","(1; 0)","(2; 0)"],"g":"2·2 − 0 = 4 > 3.","a":3},"ex":[{"t":"mc","q":"Bất phương trình nào là bất phương trình bậc nhất hai ẩn?","o":["2x − 3y ≤ 5","xy < 2","x² + y > 1","1/x + y ≥ 0"],"g":"Chỉ có x, y bậc nhất.","a":0},{"t":"mc","q":"Miền nghiệm của bất phương trình x + y ≤ 2 chứa điểm nào?","o":["(1; 2)","(0; 0)","(2; 1)","(3; 0)"],"g":"0 + 0 ≤ 2.","a":1},{"t":"tf","q":"Cho bất phương trình 3x + 2y ≤ 12.","s":[["(0; 0) là một nghiệm",true],["(4; 0) là một nghiệm",true],["(2; 4) là một nghiệm",false],["Đường bờ của miền nghiệm đi qua điểm (0; 6)",true]],"g":"3·2 + 2·4 = 14 > 12."},{"t":"sa","q":"Có bao nhiêu cặp số nguyên dương (x; y) thỏa mãn x + y ≤ 4?","a":"6","g":"(1;1), (1;2), (1;3), (2;1), (2;2), (3;1).","r":""},{"t":"sa","q":"Có 300 nghìn đồng mua bút (10 nghìn đồng/cái) và vở (15 nghìn đồng/quyển). Nếu mua 12 cái bút thì mua được nhiều nhất bao nhiêu quyển vở?","a":"12","g":"10·12 + 15y ≤ 300 ⇒ y ≤ 12.","r":""}]},{"id":"10-II-4","ten":"Bài 4. Hệ bất phương trình bậc nhất hai ẩn","ycc":["Biểu diễn miền nghiệm của hệ bất phương trình bậc nhất hai ẩn.","Vận dụng vào bài toán tìm giá trị lớn nhất, nhỏ nhất (quy hoạch tuyến tính) trong thực tế."],"kt":["Miền nghiệm của hệ là phần giao các miền nghiệm của từng bất phương trình.","Khi miền nghiệm là đa giác, biểu thức F = ax + by đạt giá trị lớn nhất, nhỏ nhất tại một trong các đỉnh.","Các bước: đặt ẩn → lập hệ điều kiện → vẽ miền nghiệm → tìm tọa độ các đỉnh → so sánh F tại các đỉnh."],"d":{"t":"mc","q":"Giá trị lớn nhất của F = x + y trên miền {x ≥ 0; y ≥ 0; x + 2y ≤ 4; 2x + y ≤ 5} là","o":["2,5","4","3","2"],"g":"Các đỉnh (0; 0), (2,5; 0), (2; 1), (0; 2); F lớn nhất bằng 3 tại (2; 1).","a":2},"ex":[{"t":"mc","q":"Điểm nào thuộc miền nghiệm của hệ {x + y ≤ 3; x ≥ 0; y ≥ 0}?","o":["(−1; 1)","(1; 1)","(2; 2)","(4; 0)"],"g":"Thỏa cả ba bất phương trình.","a":1},{"t":"mc","q":"Miền nghiệm là tam giác có các đỉnh O(0; 0), A(3; 0), B(0; 4). Giá trị lớn nhất của F = 2x + y là","o":["10","4","7","6"],"g":"F(A) = 6, F(B) = 4.","a":3},{"t":"tf","q":"Cho hệ {x ≥ 0; y ≥ 0; x + y ≤ 5; x − y ≥ −1}.","s":[["Điểm O thuộc miền nghiệm",true],["Điểm (2; 3) thuộc miền nghiệm",true],["Miền nghiệm là một tứ giác",true],["Giá trị lớn nhất của F = x + 2y trên miền nghiệm bằng 10",false]],"g":"Các đỉnh (0; 0), (5; 0), (2; 3), (0; 1); F lớn nhất bằng 8 tại (2; 3)."},{"t":"sa","q":"Cho hệ {x ≥ 0; y ≥ 0; x + y ≤ 5; x − y ≥ −1}. Tìm giá trị nhỏ nhất của F = x − y trên miền nghiệm.","a":"−1","g":"F tại các đỉnh: 0; 5; −1; −1.","r":""},{"t":"sa","q":"Một xưởng làm hai loại sản phẩm. Mỗi sản phẩm loại I cần 1 giờ máy và 2 kg nguyên liệu, lãi 3 triệu đồng; loại II cần 2 giờ máy và 1 kg nguyên liệu, lãi 5 triệu đồng. Mỗi ngày có tối đa 12 giờ máy và 12 kg nguyên liệu. Tiền lãi lớn nhất mỗi ngày là bao nhiêu triệu đồng?","a":"32","g":"x + 2y ≤ 12, 2x + y ≤ 12; các đỉnh (6; 0), (4; 4), (0; 6); lãi lớn nhất 3·4 + 5·4 = 32.","r":""}]}]},{"id":"10-III","so":"III","ten":"Hệ thức lượng trong tam giác","hk":1,"lessons":[{"id":"10-III-5","ten":"Bài 5. Giá trị lượng giác của một góc từ 0° đến 180°","ycc":["Nhận biết giá trị lượng giác của một góc từ 0° đến 180°.","Tính giá trị lượng giác của một góc bằng máy tính cầm tay; dùng quan hệ giữa các góc bù nhau."],"kt":["Trên nửa đường tròn đơn vị, điểm M(x₀; y₀) ứng với góc α thì sin α = y₀, cos α = x₀.","tan α = sin α / cos α (α ≠ 90°); cot α = cos α / sin α (0° < α < 180°).","Góc bù nhau: sin(180° − α) = sin α; cos(180° − α) = −cos α; tan(180° − α) = −tan α.","Với 90° < α < 180° thì sin α > 0 và cos α < 0.","Hệ thức cơ bản: sin²α + cos²α = 1."],"d":{"t":"mc","q":"Giá trị của sin 150° là","o":["1/2","−1/2","−√3/2","√3/2"],"g":"sin 150° = sin(180° − 30°) = sin 30° = 1/2.","a":0},"ex":[{"t":"mc","q":"Giá trị của cos 120° là","o":["1/2","−√3/2","−1/2","√3/2"],"g":"cos 120° = −cos 60° = −1/2.","a":2},{"t":"mc","q":"Với 90° < α < 180°, khẳng định nào đúng?","o":["cos α > 0","tan α > 0","sin α < 0","cos α < 0"],"g":"Góc tù có điểm M nằm bên trái trục tung nên hoành độ âm, tức cos α < 0.","a":3},{"t":"tf","q":"Cho góc α = 135°.","s":[["sin α = √2/2",true],["cos α = √2/2",false],["tan α = −1",true],["sin²α + cos²α = 1",true]],"g":"sin 135° = sin 45° = √2/2; cos 135° = −cos 45° = −√2/2; tan 135° = −1."},{"t":"sa","q":"Tính giá trị biểu thức sin²30° + cos²60° + tan 45°.","a":"1,5","g":"1/4 + 1/4 + 1 = 1,5.","r":""},{"t":"sa","q":"Cho cos α = −3/5 với 90° < α < 180°. Tính sin α.","a":"0,8","g":"sin²α = 1 − 9/25 = 16/25, mà sin α > 0 nên sin α = 4/5 = 0,8.","r":""}]},{"id":"10-III-6","ten":"Bài 6. Hệ thức lượng trong tam giác","ycc":["Giải thích và vận dụng định lí côsin, định lí sin, các công thức tính diện tích tam giác.","Giải tam giác và vận dụng vào bài toán thực tế."],"kt":["Định lí côsin: a² = b² + c² − 2bc·cos A.","Định lí sin: a / sin A = b / sin B = c / sin C = 2R (R là bán kính đường tròn ngoại tiếp).","Diện tích: S = ½·bc·sin A = abc / (4R) = p·r (p là nửa chu vi, r là bán kính đường tròn nội tiếp).","Công thức Heron: S = √(p(p − a)(p − b)(p − c))."],"d":{"t":"mc","q":"Tam giác ABC có AB = 3, AC = 5, góc A = 60°. Độ dài BC là","o":["√34","4","√19","√24"],"g":"BC² = 9 + 25 − 2·3·5·cos 60° = 19.","a":2},"ex":[{"t":"mc","q":"Tam giác có ba cạnh a = 5, b = 3, c = 7. Góc C bằng","o":["90°","120°","150°","60°"],"g":"cos C = (25 + 9 − 49) / (2·5·3) = −1/2 nên C = 120°.","a":1},{"t":"mc","q":"Tam giác ABC có AB = 4, AC = 6, góc A = 30°. Diện tích tam giác là","o":["12","6√3","6","3"],"g":"S = ½·4·6·sin 30° = 6.","a":2},{"t":"tf","q":"Tam giác ABC có BC = a = 6 và góc A = 30°.","s":[["Bán kính đường tròn ngoại tiếp R = 6",true],["Nếu góc B = 90° thì AC = 12",true],["sin A = 1/2",true],["R = 12",false]],"g":"a / sin A = 2R ⇒ 2R = 12, R = 6. Khi B = 90°: b = 2R·sin B = 12."},{"t":"sa","q":"Tính diện tích tam giác có ba cạnh 13, 14, 15.","a":"84","g":"p = 21; S = √(21·8·7·6) = 84.","r":""},{"t":"sa","q":"Hai điểm A, B cách nhau 100 m cùng nhìn cột mốc C với góc CAB = 60°, góc CBA = 75°. Tính khoảng cách AC (mét).","a":"137","g":"Góc C = 45°. AC = AB·sin B / sin C = 100·sin 75° / sin 45° ≈ 136,6 m.","r":"Làm tròn đến hàng đơn vị"}]}]},{"id":"10-IV","so":"IV","ten":"Vectơ","hk":1,"lessons":[{"id":"10-IV-7","ten":"Bài 7. Các khái niệm mở đầu","ycc":["Nhận biết khái niệm vectơ, vectơ bằng nhau, vectơ-không.","Biểu thị được một số đại lượng trong thực tiễn bằng vectơ."],"kt":["Vectơ là đoạn thẳng có hướng; độ dài vectơ AB là độ dài đoạn AB.","Hai vectơ cùng phương nếu giá của chúng song song hoặc trùng nhau; cùng phương thì cùng hướng hoặc ngược hướng.","Hai vectơ bằng nhau nếu cùng hướng và cùng độ dài.","Vectơ-không có điểm đầu trùng điểm cuối, cùng phương và cùng hướng với mọi vectơ."],"d":{"t":"mc","q":"Cho hình bình hành ABCD. Vectơ AB bằng vectơ nào?","o":["Vectơ DC","Vectơ BC","Vectơ AD","Vectơ CD"],"g":"AB và DC cùng hướng, cùng độ dài.","a":0},"ex":[{"t":"mc","q":"Cho ba điểm A, B, C phân biệt. Số vectơ khác vectơ-không có điểm đầu và điểm cuối là hai trong ba điểm đó là","o":["6","3","9","4"],"g":"Mỗi cặp điểm cho 2 vectơ: 3 cặp × 2 = 6.","a":0},{"t":"mc","q":"Hai vectơ bằng nhau khi và chỉ khi","o":["Chúng cùng hướng và cùng độ dài","Chúng cùng độ dài","Chúng cùng phương","Chúng có chung điểm đầu"],"g":"Định nghĩa hai vectơ bằng nhau.","a":0},{"t":"tf","q":"Cho lục giác đều ABCDEF tâm O.","s":[["Vectơ AB bằng vectơ ED",true],["Vectơ OA bằng vectơ DO",true],["|vectơ AB| = |vectơ OA|",true],["Vectơ AB và vectơ CD cùng phương",false]],"g":"Trong lục giác đều, AB song song và bằng ED; A, O, D thẳng hàng với O là trung điểm AD; cạnh bằng bán kính."},{"t":"sa","q":"Cho hình vuông ABCD cạnh 4. Tính độ dài vectơ AC.","a":"5,66","g":"|AC| = 4√2 ≈ 5,66.","r":"Làm tròn đến hàng phần trăm"},{"t":"sa","q":"Cho hình chữ nhật ABCD có AB = 3, BC = 4. Tính độ dài vectơ BD.","a":"5","g":"BD = √(9 + 16) = 5.","r":""}]},{"id":"10-IV-8","ten":"Bài 8. Tổng và hiệu của hai vectơ","ycc":["Thực hiện phép cộng, trừ hai vectơ; dùng quy tắc ba điểm, quy tắc hình bình hành.","Vận dụng tính chất trung điểm, trọng tâm."],"kt":["Quy tắc ba điểm: AB + BC = AC; với phép trừ: OB − OA = AB.","Quy tắc hình bình hành ABCD: AB + AD = AC.","I là trung điểm AB ⇔ IA + IB = 0.","G là trọng tâm tam giác ABC ⇔ GA + GB + GC = 0."],"d":{"t":"mc","q":"Cho tam giác ABC, M là trung điểm BC. Tổng vectơ AB + vectơ AC bằng","o":["Vectơ AM","2·vectơ MA","Vectơ BC","2·vectơ AM"],"g":"Theo quy tắc trung điểm.","a":3},"ex":[{"t":"mc","q":"Với ba điểm A, B, C bất kỳ, vectơ AB + vectơ BC bằng","o":["Vectơ CA","Vectơ BA","Vectơ AC","Vectơ-không"],"g":"Quy tắc ba điểm.","a":2},{"t":"mc","q":"G là trọng tâm tam giác ABC khi và chỉ khi","o":["GA + GB = GC","GA + GB + GC = 0","GA = GB = GC","AG = GB + GC"],"g":"Tính chất trọng tâm.","a":1},{"t":"tf","q":"Cho hình vuông ABCD cạnh 2.","s":[["AB + AD = AC",true],["|AB + AD| = 2√2",true],["AB − AD = DB",true],["|AB − AD| = 2",false]],"g":"AB + AD = AC có độ dài 2√2; AB − AD = DB có độ dài 2√2."},{"t":"sa","q":"Cho tam giác đều ABC cạnh 3. Tính |vectơ AB + vectơ AC|.","a":"5,2","g":"AB + AC = 2AM với AM = 3√3/2, nên độ dài là 3√3 ≈ 5,2.","r":"Làm tròn đến hàng phần mười"},{"t":"sa","q":"Cho tam giác đều ABC cạnh 3. Tính |vectơ AB − vectơ AC|.","a":"3","g":"AB − AC = CB, độ dài 3.","r":""}]},{"id":"10-IV-9","ten":"Bài 9. Tích của một vectơ với một số","ycc":["Thực hiện phép nhân vectơ với một số; nhận biết điều kiện hai vectơ cùng phương.","Chứng minh ba điểm thẳng hàng bằng vectơ."],"kt":["k·a cùng hướng với a nếu k > 0, ngược hướng nếu k < 0; |k·a| = |k|·|a|.","b cùng phương với a (a ≠ 0) ⇔ có số k để b = k·a.","A, B, C thẳng hàng ⇔ có số k ≠ 0 để AB = k·AC.","I là trung điểm AB, với mọi điểm M: MA + MB = 2·MI."],"d":{"t":"mc","q":"Nếu vectơ AB = −3·vectơ AC thì ba điểm A, B, C","o":["Thẳng hàng","Tạo thành tam giác vuông","Không xác định được","Tạo thành tam giác"],"g":"AB và AC cùng phương, chung điểm A.","a":0},"ex":[{"t":"mc","q":"I là trung điểm AB. Với mọi điểm M, vectơ MA + vectơ MB bằng","o":["Vectơ MI","Vectơ-không","2·vectơ MI","Vectơ AB"],"g":"Tính chất trung điểm.","a":2},{"t":"mc","q":"Cho |a| = 2. Độ dài vectơ −3a là","o":["−6","5","2/3","6"],"g":"|−3a| = 3·2 = 6.","a":3},{"t":"tf","q":"Cho vectơ a ≠ 0 và u = 2a.","s":[["u cùng phương với a",true],["u ngược hướng với a",false],["|u| = 2|a|",true],["u − 2a là vectơ-không",true]],"g":"k = 2 > 0 nên u cùng hướng a."},{"t":"sa","q":"Đoạn AB = 6, điểm M thuộc đoạn AB thỏa vectơ AM = (1/3)·vectơ AB. Tính MB.","a":"4","g":"AM = 2 nên MB = 4.","r":""},{"t":"sa","q":"Cho C là trung điểm AB. Tìm k sao cho vectơ AB = k·vectơ AC.","a":"2","g":"AC = ½AB nên AB = 2AC.","r":""}]},{"id":"10-IV-10","ten":"Bài 10. Vectơ trong mặt phẳng tọa độ","ycc":["Nhận biết tọa độ của vectơ; biểu thức tọa độ của phép cộng, trừ, nhân vectơ với số.","Tính tọa độ trung điểm, trọng tâm; vận dụng vào bài toán thực tế."],"kt":["A(x_A; y_A), B(x_B; y_B) ⇒ vectơ AB = (x_B − x_A; y_B − y_A), |AB| = √((x_B − x_A)² + (y_B − y_A)²).","a ± b = (a₁ ± b₁; a₂ ± b₂); k·a = (ka₁; ka₂).","Trung điểm I: ((x_A + x_B)/2; (y_A + y_B)/2). Trọng tâm G: trung bình cộng tọa độ ba đỉnh.","a = (a₁; a₂) và b = (b₁; b₂) cùng phương ⇔ a₁b₂ − a₂b₁ = 0."],"d":{"t":"mc","q":"Cho A(1; 2), B(3; −4). Tọa độ vectơ AB là","o":["(2; 6)","(−2; 6)","(4; −2)","(2; −6)"],"g":"(3 − 1; −4 − 2).","a":3},"ex":[{"t":"mc","q":"Trung điểm của đoạn thẳng với A(1; 3), B(5; −1) là","o":["(4; −4)","(6; 2)","(2; −2)","(3; 1)"],"g":"((1 + 5)/2; (3 − 1)/2).","a":3},{"t":"mc","q":"Cho a = (2; −1), b = (1; 3). Tọa độ a + 2b là","o":["(4; 2)","(3; 2)","(5; 4)","(4; 5)"],"g":"(2 + 2; −1 + 6).","a":3},{"t":"tf","q":"Cho A(0; 1), B(2; 3), C(4; 5).","s":[["Vectơ AB = (2; 2)",true],["A, B, C thẳng hàng",true],["Trọng tâm tam giác (nếu có) là G(2; 3)",true],["|AB| = 4",false]],"g":"AC = (4; 4) = 2AB nên thẳng hàng; |AB| = 2√2."},{"t":"sa","q":"Tính chu vi tam giác ABC với A(1; 1), B(4; 1), C(1; 5).","a":"12","g":"AB = 3, AC = 4, BC = 5.","r":""},{"t":"sa","q":"Tìm m để a = (m; 2) và b = (3; 6) cùng phương.","a":"1","g":"m·6 − 2·3 = 0 ⇒ m = 1.","r":""}]},{"id":"10-IV-11","ten":"Bài 11. Tích vô hướng của hai vectơ","ycc":["Nhận biết góc giữa hai vectơ, tích vô hướng; biểu thức tọa độ của tích vô hướng.","Vận dụng tích vô hướng để tính góc, chứng minh vuông góc và giải bài toán thực tế (công của lực)."],"kt":["a·b = |a|·|b|·cos(a, b).","Tọa độ: a·b = a₁b₁ + a₂b₂; |a| = √(a₁² + a₂²).","a ⊥ b ⇔ a·b = 0.","cos(a, b) = a·b / (|a|·|b|). Công của lực F làm vật dời theo vectơ d: A = F·d."],"d":{"t":"mc","q":"Lực F = (3; 4) (N) kéo một vật dời chỗ theo vectơ d = (5; 0) (m). Công của lực F là","o":["20 J","25 J","15 J","35 J"],"g":"A = 3·5 + 4·0 = 15.","a":2},"ex":[{"t":"mc","q":"Cho a = (1; 2), b = (4; −2). Khẳng định đúng là","o":["a·b = 8","a cùng hướng b","a ⊥ b","|a| = |b|"],"g":"a·b = 4 − 4 = 0.","a":2},{"t":"mc","q":"Cho |a| = 3, |b| = 4, góc giữa hai vectơ là 60°. Tích a·b bằng","o":["7","6√3","12","6"],"g":"3·4·cos 60° = 6.","a":3},{"t":"tf","q":"Cho a = (1; 1), b = (1; 0).","s":[["a·b = 1",true],["|a| = √2",true],["Góc giữa a và b là 45°",true],["a ⊥ b",false]],"g":"cos = 1/√2 nên góc 45°."},{"t":"sa","q":"Cho tam giác đều ABC cạnh 2. Tính vectơ AB · vectơ AC.","a":"2","g":"2·2·cos 60° = 2.","r":""},{"t":"sa","q":"Tìm m để a = (m; 3) vuông góc với b = (2; −4).","a":"6","g":"2m − 12 = 0.","r":""}]}]},{"id":"10-VI","so":"VI","ten":"Hàm số, đồ thị và ứng dụng","hk":2,"lessons":[{"id":"10-VI-15","ten":"Bài 15. Hàm số","ycc":["Nhận biết hàm số, tập xác định, tập giá trị, đồ thị.","Nhận biết tính đồng biến, nghịch biến dựa vào đồ thị; vận dụng hàm số vào bài toán thực tế."],"kt":["Hàm số y = f(x): mỗi x thuộc tập xác định D cho đúng một giá trị y.","Tập xác định: mẫu khác 0, biểu thức dưới căn bậc hai không âm.","Đồng biến trên K nếu x₁ < x₂ ⇒ f(x₁) < f(x₂); nghịch biến nếu x₁ < x₂ ⇒ f(x₁) > f(x₂).","Đồ thị là tập các điểm (x; f(x)) với x ∈ D."],"d":{"t":"mc","q":"Tập xác định của hàm số y = 1/(x − 2) là","o":["(2; +∞)","ℝ \\ {−2}","ℝ \\ {2}","ℝ"],"g":"Mẫu khác 0 ⇔ x ≠ 2.","a":2},"ex":[{"t":"mc","q":"Tập xác định của hàm số y = √(x − 1) là","o":["(1; +∞)","ℝ","(−∞; 1]","[1; +∞)"],"g":"x − 1 ≥ 0.","a":3},{"t":"mc","q":"Hàm số y = −2x + 1","o":["Đồng biến trên ℝ","Không đổi","Đồng biến trên (0; +∞)","Nghịch biến trên ℝ"],"g":"Hệ số góc âm.","a":3},{"t":"tf","q":"Cho hàm số f(x) = x² − 1.","s":[["f(2) = 3",true],["Điểm (1; 0) thuộc đồ thị",true],["f(−x) = f(x) với mọi x",true],["f đồng biến trên ℝ",false]],"g":"f giảm trên (−∞; 0), tăng trên (0; +∞)."},{"t":"sa","q":"Cho f(x) = 2x + 3. Tính f(−1).","a":"1","g":"−2 + 3 = 1.","r":""},{"t":"sa","q":"Cước taxi: 12 nghìn đồng cho km đầu tiên, mỗi km tiếp theo 10 nghìn đồng. Đi 5 km phải trả bao nhiêu nghìn đồng?","a":"52","g":"12 + 4·10 = 52.","r":""}]},{"id":"10-VI-16","ten":"Bài 16. Hàm số bậc hai","ycc":["Thiết lập bảng giá trị, vẽ và nhận biết các tính chất của đồ thị hàm số bậc hai (đỉnh, trục đối xứng, chiều biến thiên).","Vận dụng hàm số bậc hai vào bài toán thực tế."],"kt":["y = ax² + bx + c (a ≠ 0) có đồ thị là parabol, đỉnh I(−b/(2a); −Δ/(4a)), trục đối xứng x = −b/(2a).","a > 0: parabol quay bề lõm lên; hàm nghịch biến trên (−∞; −b/(2a)), đồng biến trên (−b/(2a); +∞); GTNN tại đỉnh.","a < 0: ngược lại; GTLN tại đỉnh.","Giao với trục hoành là nghiệm của ax² + bx + c = 0."],"d":{"t":"mc","q":"Đồ thị hàm số y = x² − 4x + 3 có trục đối xứng là","o":["x = −2","x = 2","x = 4","x = 3"],"g":"x = −b/(2a) = 2.","a":1},"ex":[{"t":"mc","q":"Đỉnh của parabol y = x² − 2x + 3 là","o":["(1; 3)","(−1; 6)","(2; 3)","(1; 2)"],"g":"x = 1, y = 1 − 2 + 3 = 2.","a":3},{"t":"mc","q":"Hàm số y = −x² + 2x + 3 đồng biến trên khoảng","o":["(−∞; 3)","(−1; 3)","(−∞; 1)","(1; +∞)"],"g":"a < 0, tăng bên trái đỉnh x = 1.","a":2},{"t":"tf","q":"Cho hàm số y = x² − 6x + 5.","s":[["Parabol quay bề lõm lên trên",true],["Đỉnh là I(3; −4)",true],["Đồ thị cắt trục hoành tại x = 1 và x = 5",true],["Giá trị nhỏ nhất của hàm số là −3",false]],"g":"GTNN là −4 tại x = 3."},{"t":"sa","q":"Độ cao quả bóng h(t) = −5t² + 20t + 1 (m). Tính độ cao lớn nhất (m).","a":"21","g":"Đỉnh t = 2, h = 21.","r":""},{"t":"sa","q":"Dùng 40 m lưới rào một mảnh đất hình chữ nhật. Diện tích lớn nhất rào được là bao nhiêu m²?","a":"100","g":"Nửa chu vi 20: S = x(20 − x) lớn nhất khi x = 10, S = 100.","r":""}]},{"id":"10-VI-17","ten":"Bài 17. Dấu của tam thức bậc hai","ycc":["Giải thích định lí về dấu của tam thức bậc hai.","Giải bất phương trình bậc hai một ẩn và vận dụng vào thực tế."],"kt":["f(x) = ax² + bx + c, Δ = b² − 4ac.","Δ < 0: f(x) cùng dấu a với mọi x.","Δ = 0: f(x) cùng dấu a với mọi x ≠ −b/(2a).","Δ > 0, hai nghiệm x₁ < x₂: f(x) trái dấu a trong (x₁; x₂), cùng dấu a ngoài đoạn [x₁; x₂]."],"d":{"t":"mc","q":"Tam thức f(x) = x² − 5x + 6 âm khi và chỉ khi","o":["x > 3","x < 2 hoặc x > 3","2 < x < 3","x < 2"],"g":"Nghiệm 2 và 3, a > 0 nên âm ở giữa hai nghiệm.","a":2},"ex":[{"t":"mc","q":"Tam thức x² + x + 1","o":["Có hai nghiệm","Đổi dấu tại x = −1","Luôn âm","Luôn dương"],"g":"Δ = −3 < 0, a > 0.","a":3},{"t":"mc","q":"Tập nghiệm của −x² + 4 ≥ 0 là","o":["(−2; 2)","ℝ","[−2; 2]","(−∞; −2] ∪ [2; +∞)"],"g":"x² ≤ 4.","a":2},{"t":"tf","q":"Cho f(x) = x² − 4x + 3.","s":[["Δ = 4",true],["f(x) < 0 khi x ∈ (1; 3)",true],["f(0) < 0",false],["f(x) ≥ 0 khi x ≤ 1 hoặc x ≥ 3",true]],"g":"f(0) = 3 > 0."},{"t":"sa","q":"Bất phương trình x² − 5x + 4 ≤ 0 có bao nhiêu nghiệm nguyên?","a":"4","g":"Tập nghiệm [1; 4] gồm 1, 2, 3, 4.","r":""},{"t":"sa","q":"Tìm số nguyên m nhỏ nhất để x² − 2x + m > 0 với mọi x.","a":"2","g":"Δ' = 1 − m < 0 ⇔ m > 1.","r":""}]},{"id":"10-VI-18","ten":"Bài 18. Phương trình quy về phương trình bậc hai","ycc":["Giải phương trình dạng √(ax² + bx + c) = √(dx² + ex + f) và √(ax² + bx + c) = dx + e."],"kt":["√A = √B: bình phương được A = B, giải rồi thử lại điều kiện A ≥ 0 (hoặc B ≥ 0).","√A = B: điều kiện B ≥ 0, bình phương được A = B².","Luôn thử lại nghiệm vào phương trình ban đầu để loại nghiệm ngoại lai."],"d":{"t":"mc","q":"Nghiệm của phương trình √(x + 3) = x + 1 là","o":["Vô nghiệm","x = 1 và x = −2","x = 1","x = −2"],"g":"x + 3 = (x + 1)² ⇒ x = 1 hoặc x = −2; điều kiện x + 1 ≥ 0 loại x = −2.","a":2},"ex":[{"t":"mc","q":"Nghiệm của phương trình √(2x − 1) = √(x + 2) là","o":["x = −3","x = 3","x = 1","Vô nghiệm"],"g":"2x − 1 = x + 2.","a":1},{"t":"mc","q":"Số nghiệm của phương trình √(x² − 3x + 2) = √(x − 1) là","o":["2","3","0","1"],"g":"x² − 4x + 3 = 0 ⇒ x = 1, x = 3; cả hai thỏa x − 1 ≥ 0.","a":0},{"t":"tf","q":"Xét phương trình √(x + 1) = x − 1.","s":[["Điều kiện để giải là x ≥ 1",true],["Bình phương hai vế được x + 1 = x² − 2x + 1",true],["Phương trình có 2 nghiệm",false],["Nghiệm của phương trình là x = 3",true]],"g":"x² − 3x = 0 ⇒ x = 0 (loại) hoặc x = 3."},{"t":"sa","q":"Tính tổng các nghiệm của phương trình √(x² + 2x + 4) = √(2x + 13).","a":"0","g":"x² = 9 ⇒ x = ±3, đều thỏa 2x + 13 ≥ 0.","r":""},{"t":"sa","q":"Giải phương trình √(3x + 1) = x − 1.","a":"5","g":"3x + 1 = x² − 2x + 1 ⇒ x = 0 (loại vì x ≥ 1) hoặc x = 5.","r":""}]}]},{"id":"10-VIII","so":"VIII","ten":"Đại số tổ hợp","hk":2,"lessons":[{"id":"10-VIII-23","ten":"Bài 23. Quy tắc đếm","ycc":["Vận dụng quy tắc cộng, quy tắc nhân và sơ đồ hình cây để đếm."],"kt":["Quy tắc cộng: công việc làm theo phương án A (m cách) hoặc B (n cách), không trùng nhau: m + n cách.","Quy tắc nhân: công việc gồm hai công đoạn liên tiếp m cách và n cách: m·n cách.","Sơ đồ hình cây giúp liệt kê các khả năng theo từng bước."],"d":{"t":"mc","q":"Một bạn có 3 áo và 4 quần. Số cách chọn một bộ quần áo là","o":["3","7","24","12"],"g":"3·4 = 12.","a":3},"ex":[{"t":"mc","q":"Từ A đến B có 3 con đường, từ B đến C có 2 con đường. Số cách đi từ A đến C qua B là","o":["5","9","6","8"],"g":"3·2.","a":2},{"t":"mc","q":"Chọn một học sinh từ 15 nam hoặc 12 nữ. Số cách chọn là","o":["180","12","27","15"],"g":"Quy tắc cộng.","a":2},{"t":"tf","q":"Lập số tự nhiên có 2 chữ số khác nhau từ các chữ số 1, 2, 3, 4.","s":[["Chữ số hàng chục có 4 cách chọn",true],["Chữ số hàng đơn vị có 3 cách chọn",true],["Lập được 16 số",false],["Có 6 số chẵn",true]],"g":"Có 4·3 = 12 số; số chẵn: hàng đơn vị là 2 hoặc 4 (2 cách), hàng chục 3 cách."},{"t":"sa","q":"Có bao nhiêu số có 3 chữ số (có thể lặp) lập từ các chữ số 1, 2, 3, 4, 5?","a":"125","g":"5·5·5.","r":""},{"t":"sa","q":"Có bao nhiêu số tự nhiên có 3 chữ số khác nhau?","a":"648","g":"Hàng trăm 9 cách (khác 0), hàng chục 9 cách, hàng đơn vị 8 cách.","r":""}]},{"id":"10-VIII-24","ten":"Bài 24. Hoán vị, chỉnh hợp và tổ hợp","ycc":["Tính số hoán vị, chỉnh hợp, tổ hợp; vận dụng vào bài toán đếm."],"kt":["Hoán vị n phần tử: Pₙ = n!.","Chỉnh hợp chập k của n (có thứ tự): Aₙᵏ = n! / (n − k)!.","Tổ hợp chập k của n (không thứ tự): Cₙᵏ = n! / (k!(n − k)!).","Có sắp thứ tự hoặc phân vai thì dùng chỉnh hợp; chỉ chọn nhóm thì dùng tổ hợp."],"d":{"t":"mc","q":"Có bao nhiêu cách chọn từ 10 học sinh một lớp trưởng và một lớp phó?","o":["90","45","100","20"],"g":"A₁₀² = 90.","a":0},"ex":[{"t":"mc","q":"Có bao nhiêu cách xếp 5 bạn thành một hàng dọc?","o":["25","120","60","5"],"g":"5! = 120.","a":1},{"t":"mc","q":"Có bao nhiêu cách chọn 3 bạn từ 7 bạn để đi trực nhật?","o":["343","21","210","35"],"g":"C₇³ = 35.","a":3},{"t":"tf","q":"Một nhóm có 10 nam và 8 nữ. Chọn 2 người.","s":[["Số cách chọn 2 người bất kỳ là 153",true],["Số cách chọn 1 nam và 1 nữ là 80",true],["Số cách chọn 2 nam là 45",true],["Số cách chọn 2 nữ là 56",false]],"g":"C₁₈² = 153; 10·8 = 80; C₁₀² = 45; C₈² = 28."},{"t":"sa","q":"Tính C₆² + A₅².","a":"35","g":"15 + 20.","r":""},{"t":"sa","q":"Một đa giác lồi 8 cạnh có bao nhiêu đường chéo?","a":"20","g":"C₈² − 8 = 20.","r":""}]},{"id":"10-VIII-25","ten":"Bài 25. Nhị thức Newton","ycc":["Khai triển nhị thức Newton (a + b)ⁿ với n ≤ 5."],"kt":["(a + b)⁴ = a⁴ + 4a³b + 6a²b² + 4ab³ + b⁴.","(a + b)⁵ = a⁵ + 5a⁴b + 10a³b² + 10a²b³ + 5ab⁴ + b⁵.","Số hạng tổng quát Cₙᵏ·aⁿ⁻ᵏ·bᵏ; khai triển có n + 1 số hạng.","Tổng các hệ số: thay a = b = 1 (hoặc x = 1)."],"d":{"t":"mc","q":"Khai triển (a + b)⁴ có bao nhiêu số hạng?","o":["6","8","5","4"],"g":"n + 1 = 5.","a":2},"ex":[{"t":"mc","q":"Hệ số của x² trong khai triển (x + 2)⁴ là","o":["32","24","16","6"],"g":"C₄²·2² = 24.","a":1},{"t":"mc","q":"Số hạng thứ ba trong khai triển (a + b)⁵ (theo lũy thừa giảm của a) là","o":["5a⁴b","5ab⁴","10a³b²","10a²b³"],"g":"C₅²a³b².","a":2},{"t":"tf","q":"Xét khai triển (1 + x)⁵.","s":[["Có 6 số hạng",true],["Hệ số của x³ là 10",true],["Tổng các hệ số bằng 32",true],["Số hạng chứa x⁴ là 4x⁴",false]],"g":"Số hạng chứa x⁴ là 5x⁴."},{"t":"sa","q":"Tìm hệ số của x³ trong khai triển (2x − 1)⁴.","a":"−32","g":"C₄³·(2x)³·(−1) = −32x³.","r":""},{"t":"sa","q":"Tính tổng các hệ số trong khai triển (2x + 1)⁴.","a":"81","g":"Thay x = 1: 3⁴ = 81.","r":""}]}]},{"id":"10-IX","so":"IX","ten":"Tính xác suất theo định nghĩa cổ điển","hk":2,"lessons":[{"id":"10-IX-26","ten":"Bài 26. Biến cố và định nghĩa cổ điển của xác suất","ycc":["Nhận biết phép thử, không gian mẫu, biến cố, biến cố đối.","Tính xác suất theo định nghĩa cổ điển."],"kt":["Không gian mẫu Ω: tập mọi kết quả có thể của phép thử.","Xác suất cổ điển: P(A) = n(A) / n(Ω) khi các kết quả đồng khả năng.","Biến cố đối: P(Ā) = 1 − P(A).","0 ≤ P(A) ≤ 1; P(Ω) = 1; P(∅) = 0."],"d":{"t":"mc","q":"Gieo một con xúc xắc cân đối. Xác suất xuất hiện mặt có số chấm chẵn là","o":["1/6","1/2","2/3","1/3"],"g":"3 mặt chẵn trên 6 mặt.","a":1},"ex":[{"t":"mc","q":"Gieo hai đồng xu. Số phần tử của không gian mẫu là","o":["8","2","3","4"],"g":"SS, SN, NS, NN.","a":3},{"t":"mc","q":"Với biến cố A bất kỳ, P(Ā) bằng","o":["P(A)","1 − P(A)","−P(A)","1 + P(A)"],"g":"Biến cố đối.","a":1},{"t":"tf","q":"Gieo một con xúc xắc cân đối hai lần.","s":[["n(Ω) = 36",true],["Xác suất tổng số chấm bằng 7 là 1/6",true],["Xác suất hai lần giống nhau là 1/6",true],["Xác suất tổng số chấm bằng 12 là 1/18",false]],"g":"Tổng 12 chỉ có (6; 6): 1/36."},{"t":"sa","q":"Hộp có 5 bi đỏ và 3 bi xanh. Lấy ngẫu nhiên 2 bi. Tính xác suất cả 2 bi đều đỏ.","a":"0,36","g":"C₅²/C₈² = 10/28 ≈ 0,36.","r":"Làm tròn đến hàng phần trăm"},{"t":"sa","q":"Chọn ngẫu nhiên một số từ 1 đến 20. Tính xác suất số đó chia hết cho 3.","a":"0,3","g":"Có 6 số: 3, 6, …, 18.","r":""}]},{"id":"10-IX-27","ten":"Bài 27. Thực hành tính xác suất theo định nghĩa cổ điển","ycc":["Tính xác suất bằng phương pháp tổ hợp; dùng biến cố đối để tính nhanh."],"kt":["Đếm n(Ω) và n(A) bằng hoán vị, chỉnh hợp, tổ hợp.","\"Ít nhất một\" thường tính qua biến cố đối: P(A) = 1 − P(không có cái nào).","Xếp chỗ \"đứng cạnh nhau\": coi nhóm đứng cạnh là một khối rồi nhân với số cách xếp trong khối."],"d":{"t":"mc","q":"Chọn ngẫu nhiên 2 bạn từ 4 nam và 6 nữ. Xác suất chọn được 1 nam và 1 nữ là","o":["4/15","8/15","1/2","2/5"],"g":"4·6 / C₁₀² = 24/45.","a":1},"ex":[{"t":"mc","q":"Xếp ngẫu nhiên 3 bạn An, Bình, Chi thành hàng. Xác suất An đứng đầu là","o":["2/3","1/3","1/6","1/2"],"g":"2!/3! = 1/3.","a":1},{"t":"mc","q":"Lấy ngẫu nhiên 3 bi từ hộp có 4 bi trắng và 5 bi đen. Xác suất có ít nhất 1 bi trắng là","o":["37/42","5/42","1/2","10/21"],"g":"1 − C₅³/C₉³ = 1 − 10/84.","a":0},{"t":"tf","q":"Lớp có 30 học sinh, trong đó 12 nữ. Chọn ngẫu nhiên 2 học sinh.","s":[["n(Ω) = 435",true],["Số cách chọn 2 nữ là 66",true],["Xác suất chọn được 2 nữ là 66/435",true],["Xác suất có ít nhất 1 nam nhỏ hơn 0,8",false]],"g":"P(ít nhất 1 nam) = 1 − 66/435 ≈ 0,85."},{"t":"sa","q":"Xếp ngẫu nhiên 5 người (trong đó có An và Bình) thành một hàng. Tính xác suất An và Bình đứng cạnh nhau.","a":"0,4","g":"2·4!/5! = 48/120.","r":""},{"t":"sa","q":"Gieo hai con xúc xắc. Tính xác suất tổng số chấm chia hết cho 5.","a":"0,19","g":"Tổng 5: 4 cách; tổng 10: 3 cách; 7/36 ≈ 0,19.","r":"Làm tròn đến hàng phần trăm"}]}]}],"11":[{"id":"11-I","so":"I","ten":"Hàm số lượng giác và phương trình lượng giác","hk":1,"lessons":[{"id":"11-I-1","ten":"Bài 1. Giá trị lượng giác của góc lượng giác","ycc":["Nhận biết góc lượng giác, số đo radian, đường tròn lượng giác.","Nhận biết giá trị lượng giác của góc lượng giác; dùng hệ thức cơ bản và giá trị lượng giác của các góc có liên quan đặc biệt."],"kt":["π rad = 180°; 1 rad = 180°/π. Độ dài cung: l = R·α (α tính bằng radian).","Điểm M trên đường tròn lượng giác ứng với góc α: cos α là hoành độ, sin α là tung độ.","sin²α + cos²α = 1; 1 + tan²α = 1/cos²α; tan α·cot α = 1.","Góc đối: cos(−α) = cos α, sin(−α) = −sin α. Góc bù: sin(π − α) = sin α. Góc phụ: sin(π/2 − α) = cos α.","Dấu: góc phần tư I tất cả dương; II sin dương; III tan, cot dương; IV cos dương."],"d":{"t":"mc","q":"Góc 180° bằng bao nhiêu radian?","o":["π/2","π","1","2π"],"g":"180° = π rad.","a":1},"ex":[{"t":"mc","q":"Góc 3π/4 rad bằng","o":["120°","45°","135°","150°"],"g":"3·180°/4 = 135°.","a":2},{"t":"mc","q":"Với π/2 < α < π, khẳng định nào đúng?","o":["tan α > 0","cos α > 0","cot α > 0","sin α > 0"],"g":"Góc phần tư II: chỉ sin dương.","a":3},{"t":"tf","q":"Cho cos α = 3/5 với 0 < α < π/2.","s":[["sin α = 4/5",true],["tan α = 4/3",true],["cot α = 4/3",false],["sin(π − α) = 4/5",true]],"g":"cot α = 3/4; sin(π − α) = sin α."},{"t":"sa","q":"Tính độ dài cung tròn (cm) của đường tròn bán kính 10 cm có số đo 1,5 rad.","a":"15","g":"l = R·α = 10·1,5.","r":""},{"t":"sa","q":"Tính sin²(π/7) + cos²(π/7) + tan(π/4).","a":"2","g":"1 + 1 = 2.","r":""}]},{"id":"11-I-2","ten":"Bài 2. Công thức lượng giác","ycc":["Mô tả và vận dụng công thức cộng, công thức nhân đôi, công thức biến đổi tích thành tổng và tổng thành tích."],"kt":["cos(a ± b) = cos a cos b ∓ sin a sin b; sin(a ± b) = sin a cos b ± cos a sin b.","sin 2a = 2 sin a cos a; cos 2a = cos²a − sin²a = 2cos²a − 1 = 1 − 2sin²a.","Hạ bậc: cos²a = (1 + cos 2a)/2; sin²a = (1 − cos 2a)/2.","Biến đổi: cos a + cos b = 2cos((a + b)/2)·cos((a − b)/2); sin a cos b = ½[sin(a + b) + sin(a − b)]."],"d":{"t":"mc","q":"Công thức nào đúng?","o":["sin 2a = 2 sin a","cos 2a = 2 cos a","sin 2a = 2 sin a cos a","cos 2a = cos²a + sin²a"],"g":"Công thức nhân đôi.","a":2},"ex":[{"t":"mc","q":"cos(a + b) bằng","o":["cos a cos b + sin a sin b","cos a cos b − sin a sin b","sin a cos b + cos a sin b","cos a + cos b"],"g":"Công thức cộng.","a":1},{"t":"mc","q":"Giá trị của sin 75° là","o":["√3/2","(√6 + √2)/4","(√3 + 1)/2","(√6 − √2)/4"],"g":"sin(45° + 30°) = sin45 cos30 + cos45 sin30.","a":1},{"t":"tf","q":"Cho sin a = 3/5 với π/2 < a < π.","s":[["cos a = −4/5",true],["sin 2a = −24/25",true],["cos 2a = 7/25",true],["tan 2a > 0",false]],"g":"sin 2a < 0, cos 2a > 0 nên tan 2a < 0."},{"t":"sa","q":"Tính cos²15° − sin²15°.","a":"0,87","g":"= cos 30° = √3/2 ≈ 0,87.","r":"Làm tròn đến hàng phần trăm"},{"t":"sa","q":"Tính 2 sin 15° cos 15°.","a":"0,5","g":"= sin 30°.","r":""}]},{"id":"11-I-3","ten":"Bài 3. Hàm số lượng giác","ycc":["Nhận biết hàm số chẵn, lẻ, tuần hoàn; tập xác định, tập giá trị, chiều biến thiên, đồ thị của các hàm số lượng giác.","Vận dụng hàm số lượng giác mô tả hiện tượng tuần hoàn."],"kt":["y = sin x, y = cos x: tập xác định ℝ, tập giá trị [−1; 1], chu kì 2π.","y = tan x: x ≠ π/2 + kπ; y = cot x: x ≠ kπ; chu kì π.","y = cos x là hàm chẵn; y = sin x, tan x, cot x là hàm lẻ.","y = sin(ax + b), y = cos(ax + b) có chu kì 2π/|a|."],"d":{"t":"mc","q":"Chu kì của hàm số y = sin x là","o":["π/2","π","2π","4π"],"g":"Chu kì tuần hoàn của sin.","a":2},"ex":[{"t":"mc","q":"Hàm số nào là hàm số chẵn?","o":["y = tan x","y = cos x","y = cot x","y = sin x"],"g":"cos(−x) = cos x.","a":1},{"t":"mc","q":"Tập giá trị của hàm số y = 3 sin x + 1 là","o":["[−1; 1]","[−3; 3]","[−2; 4]","[1; 4]"],"g":"3 sin x ∈ [−3; 3].","a":2},{"t":"tf","q":"Cho hàm số y = 2 cos x.","s":[["Tập xác định là ℝ",true],["Giá trị lớn nhất bằng 2",true],["Chu kì bằng π",false],["Là hàm số chẵn",true]],"g":"Chu kì 2π."},{"t":"sa","q":"Chu kì của hàm số y = sin 2x là bao nhiêu?","a":"3,14","g":"T = 2π/2 = π ≈ 3,14.","r":"Làm tròn đến hàng phần trăm"},{"t":"sa","q":"Tìm giá trị lớn nhất của y = 5 − 3 cos x.","a":"8","g":"Khi cos x = −1.","r":""}]},{"id":"11-I-4","ten":"Bài 4. Phương trình lượng giác cơ bản","ycc":["Nhận biết công thức nghiệm của các phương trình lượng giác cơ bản; giải phương trình bằng công thức hoặc máy tính cầm tay.","Giải bài toán thực tế dẫn đến phương trình lượng giác."],"kt":["sin x = sin α ⇔ x = α + k2π hoặc x = π − α + k2π.","cos x = cos α ⇔ x = ±α + k2π.","tan x = tan α ⇔ x = α + kπ; cot x = cot α ⇔ x = α + kπ.","Trường hợp đặc biệt: sin x = 0 ⇔ x = kπ; cos x = 0 ⇔ x = π/2 + kπ."],"d":{"t":"mc","q":"Nghiệm của phương trình sin x = 1/2 là","o":["x = π/6 + kπ","x = π/3 + k2π","x = π/6 + k2π hoặc x = 5π/6 + k2π","x = ±π/6 + k2π"],"g":"sin x = sin(π/6).","a":2},"ex":[{"t":"mc","q":"cos x = 0 khi và chỉ khi","o":["x = k2π","x = kπ","x = π/2 + k2π","x = π/2 + kπ"],"g":"Trường hợp đặc biệt.","a":3},{"t":"mc","q":"Nghiệm của phương trình tan x = 1 là","o":["x = π/4 + kπ","x = −π/4 + kπ","x = π/4 + k2π","x = π/2 + kπ"],"g":"tan x = tan(π/4).","a":0},{"t":"tf","q":"Xét phương trình 2 sin x − 1 = 0 trên đoạn [0; 2π].","s":[["Phương trình tương đương sin x = 1/2",true],["x = π/6 là một nghiệm",true],["x = 5π/6 là một nghiệm",true],["Phương trình có 4 nghiệm trên [0; 2π]",false]],"g":"Chỉ có 2 nghiệm π/6 và 5π/6."},{"t":"sa","q":"Phương trình cos x = 1/2 có bao nhiêu nghiệm trên đoạn [0; 4π]?","a":"4","g":"π/3, 5π/3, 7π/3, 11π/3.","r":""},{"t":"sa","q":"Độ cao cabin vòng quay h(t) = 30 + 20 sin(πt/15) (m), t tính bằng phút. Sau bao nhiêu phút cabin lên cao nhất lần đầu?","a":"7,5","g":"sin(πt/15) = 1 ⇒ πt/15 = π/2.","r":""}]}]},{"id":"11-II","so":"II","ten":"Dãy số. Cấp số cộng và cấp số nhân","hk":1,"lessons":[{"id":"11-II-5","ten":"Bài 5. Dãy số","ycc":["Nhận biết dãy số hữu hạn, vô hạn; cách cho dãy số; dãy số tăng, giảm, bị chặn."],"kt":["Dãy số có thể cho bằng công thức số hạng tổng quát, hệ thức truy hồi hoặc mô tả.","Dãy tăng: uₙ₊₁ > uₙ với mọi n; dãy giảm: uₙ₊₁ < uₙ.","Bị chặn trên: uₙ ≤ M; bị chặn dưới: uₙ ≥ m; bị chặn: cả hai."],"d":{"t":"mc","q":"Cho dãy số uₙ = 2n + 1. Số hạng u₃ là","o":["5","7","9","6"],"g":"2·3 + 1.","a":1},"ex":[{"t":"mc","q":"Dãy số nào là dãy giảm?","o":["uₙ = 1/n","uₙ = (−1)ⁿ","uₙ = n²","uₙ = 2n"],"g":"1/n giảm khi n tăng.","a":0},{"t":"mc","q":"Cho u₁ = 1, uₙ₊₁ = 2uₙ + 1. Số hạng u₃ là","o":["15","5","3","7"],"g":"u₂ = 3, u₃ = 7.","a":3},{"t":"tf","q":"Cho dãy số uₙ = n² − 4n.","s":[["u₁ = −3",true],["u₄ = 0",true],["Dãy số tăng",false],["Dãy bị chặn dưới bởi −4",true]],"g":"u₁ = −3 > u₂ = −4 nên không tăng; uₙ = (n − 2)² − 4 ≥ −4."},{"t":"sa","q":"Cho uₙ = (n + 1)/(n + 2). Tính u₈.","a":"0,9","g":"9/10.","r":""},{"t":"sa","q":"Cho uₙ = 3n − 5. Số 25 là số hạng thứ mấy?","a":"10","g":"3n − 5 = 25.","r":""}]},{"id":"11-II-6","ten":"Bài 6. Cấp số cộng","ycc":["Nhận biết cấp số cộng; tính số hạng tổng quát và tổng n số hạng đầu.","Giải bài toán thực tế gắn với cấp số cộng."],"kt":["Cấp số cộng: uₙ₊₁ = uₙ + d (d là công sai).","uₙ = u₁ + (n − 1)d.","Sₙ = n(u₁ + uₙ)/2 = n[2u₁ + (n − 1)d]/2.","Ba số a, b, c lập cấp số cộng ⇔ a + c = 2b."],"d":{"t":"mc","q":"Cấp số cộng có u₁ = 2, d = 3. Số hạng u₅ là","o":["14","11","17","15"],"g":"2 + 4·3.","a":0},"ex":[{"t":"mc","q":"Dãy số nào là cấp số cộng?","o":["2; 5; 8; 11","1; 4; 9; 16","3; 3,5; 4,5; 6","1; 2; 4; 8"],"g":"Hiệu không đổi bằng 3.","a":0},{"t":"mc","q":"Tổng 10 số hạng đầu của cấp số cộng u₁ = 1, d = 2 là","o":["110","100","90","50"],"g":"S₁₀ = 10(2 + 18)/2.","a":1},{"t":"tf","q":"Cho cấp số cộng u₁ = 5, d = −2.","s":[["u₂ = 3",true],["u₁₀ = −13",true],["S₅ = 5",true],["Dãy số tăng",false]],"g":"d < 0 nên dãy giảm."},{"t":"sa","q":"Cấp số cộng có u₃ = 7 và u₇ = 19. Tính u₂₀.","a":"58","g":"d = 3, u₁ = 1, u₂₀ = 1 + 19·3.","r":""},{"t":"sa","q":"Rạp hát có 20 hàng ghế, hàng đầu 15 ghế, mỗi hàng sau nhiều hơn hàng trước 2 ghế. Rạp có bao nhiêu ghế?","a":"680","g":"S₂₀ = 20(2·15 + 19·2)/2.","r":""}]},{"id":"11-II-7","ten":"Bài 7. Cấp số nhân","ycc":["Nhận biết cấp số nhân; tính số hạng tổng quát và tổng n số hạng đầu.","Giải bài toán thực tế gắn với cấp số nhân (lãi kép, tăng trưởng)."],"kt":["Cấp số nhân: uₙ₊₁ = uₙ·q (q là công bội).","uₙ = u₁·qⁿ⁻¹.","Sₙ = u₁(1 − qⁿ)/(1 − q) với q ≠ 1.","Tăng trưởng r% mỗi kì: giá trị sau n kì là A·(1 + r)ⁿ."],"d":{"t":"mc","q":"Cấp số nhân có u₁ = 3, q = 2. Số hạng u₅ là","o":["96","24","30","48"],"g":"3·2⁴.","a":3},"ex":[{"t":"mc","q":"Dãy số nào là cấp số nhân?","o":["1; 3; 6; 10","1; 4; 9; 16","2; 5; 8; 11","1; 2; 4; 8"],"g":"Công bội 2.","a":3},{"t":"mc","q":"Tổng 5 số hạng đầu của cấp số nhân u₁ = 1, q = 2 là","o":["63","31","32","16"],"g":"2⁵ − 1.","a":1},{"t":"tf","q":"Cho cấp số nhân u₁ = 2, q = 3.","s":[["u₂ = 6",true],["u₄ = 54",true],["S₃ = 26",true],["uₙ = 2·3ⁿ",false]],"g":"uₙ = 2·3ⁿ⁻¹."},{"t":"sa","q":"Lương khởi điểm 8 triệu đồng/tháng, mỗi năm tăng 5% so với năm trước. Lương tháng ở năm thứ 3 là bao nhiêu triệu đồng?","a":"8,82","g":"8·1,05².","r":""},{"t":"sa","q":"Cấp số nhân có u₂ = 6, u₅ = 48. Tính tổng 6 số hạng đầu.","a":"189","g":"q³ = 8 ⇒ q = 2, u₁ = 3; S₆ = 3(2⁶ − 1).","r":""}]}]},{"id":"11-III","so":"III","ten":"Các số đặc trưng đo xu thế trung tâm của mẫu số liệu ghép nhóm","hk":2,"lessons":[{"id":"11-III-8","ten":"Bài 8. Mẫu số liệu ghép nhóm","ycc":["Đọc và giải thích mẫu số liệu ghép nhóm; lập bảng tần số ghép nhóm."],"kt":["Mẫu số liệu ghép nhóm chia dữ liệu thành các nhóm [a; b) có độ dài bằng nhau.","Giá trị đại diện của nhóm [a; b) là (a + b)/2.","Tần số của nhóm là số giá trị thuộc nhóm; tần số tương đối = tần số / cỡ mẫu.","Tần số tích lũy của một nhóm = tổng tần số của nhóm đó và các nhóm trước."],"d":{"t":"mc","q":"Giá trị đại diện của nhóm [10; 20) là","o":["20","30","15","10"],"g":"Trung điểm của nhóm.","a":2},"ex":[{"t":"mc","q":"Độ dài của nhóm [20; 25) là","o":["25","20","5","22,5"],"g":"25 − 20.","a":2},{"t":"mc","q":"Tổng các tần số trong bảng tần số ghép nhóm bằng","o":["Số nhóm","Cỡ mẫu","Độ dài nhóm","Giá trị lớn nhất"],"g":"Mỗi giá trị thuộc đúng một nhóm.","a":1},{"t":"tf","q":"Chiều cao (cm) của một lớp: [150; 155): 5; [155; 160): 12; [160; 165): 8; [165; 170): 5.","s":[["Cỡ mẫu là 30",true],["Giá trị đại diện của nhóm [155; 160) là 157,5",true],["Nhóm có tần số lớn nhất là [160; 165)",false],["Có 13 bạn cao từ 160 cm trở lên",true]],"g":"Nhóm tần số lớn nhất là [155; 160)."},{"t":"sa","q":"Chiều cao (cm) của một lớp: [150; 155): 5; [155; 160): 12; [160; 165): 8; [165; 170): 5. Tính tần số tương đối của nhóm [155; 160).","a":"0,4","g":"12/30.","r":""},{"t":"sa","q":"Chiều cao (cm) của một lớp: [150; 155): 5; [155; 160): 12; [160; 165): 8; [165; 170): 5. Có bao nhiêu bạn cao dưới 160 cm?","a":"17","g":"5 + 12.","r":""}]},{"id":"11-III-9","ten":"Bài 9. Các số đặc trưng đo xu thế trung tâm","ycc":["Tính số trung bình, trung vị, tứ phân vị, mốt của mẫu số liệu ghép nhóm và giải thích ý nghĩa."],"kt":["Số trung bình: x̄ = (n₁x₁ + n₂x₂ + … + nₖxₖ)/n với xᵢ là giá trị đại diện.","Trung vị: Mₑ = uₘ + ((n/2 − C)/nₘ)·h, với [uₘ; uₘ₊₁) là nhóm chứa trung vị, C là tần số tích lũy trước nhóm đó.","Tứ phân vị Q₁, Q₃ tính tương tự với n/4 và 3n/4.","Mốt: M₀ = uₘ + ((nₘ − nₘ₋₁)/((nₘ − nₘ₋₁) + (nₘ − nₘ₊₁)))·h, với nhóm chứa mốt có tần số lớn nhất."],"d":{"t":"mc","q":"Mẫu số liệu: [0; 10) tần số 4, [10; 20) tần số 6. Số trung bình là","o":["10","11","12","15"],"g":"(5·4 + 15·6)/10.","a":1},"ex":[{"t":"mc","q":"Nhóm chứa mốt là nhóm","o":["Đầu tiên","Có tần số lớn nhất","Có giá trị đại diện lớn nhất","Đứng giữa bảng"],"g":"Định nghĩa.","a":1},{"t":"mc","q":"Với bảng chiều cao [150; 155): 5; [155; 160): 12; [160; 165): 8; [165; 170): 5, nhóm chứa trung vị là","o":["[150; 155)","[160; 165)","[155; 160)","[165; 170)"],"g":"n/2 = 15; tần số tích lũy 5, 17.","a":2},{"t":"tf","q":"Thời gian tự học Toán (giờ/tuần) của 40 học sinh: [0; 2): 10; [2; 4): 18; [4; 6): 8; [6; 8): 4.","s":[["Cỡ mẫu n = 40",true],["Nhóm chứa mốt là [2; 4)",true],["Số trung bình xấp xỉ 3,3 giờ",true],["Mốt xấp xỉ 3,5 giờ",false]],"g":"x̄ = (10 + 54 + 40 + 28)/40 = 3,3; M₀ = 2 + 8/18·2 ≈ 2,89."},{"t":"sa","q":"Thời gian tự học Toán (giờ/tuần) của 40 học sinh: [0; 2): 10; [2; 4): 18; [4; 6): 8; [6; 8): 4. Tính mốt (giờ).","a":"2,89","g":"M₀ = 2 + (18 − 10)/((18 − 10) + (18 − 8))·2.","r":"Làm tròn đến hàng phần trăm"},{"t":"sa","q":"Chiều cao (cm) của một lớp: [150; 155): 5; [155; 160): 12; [160; 165): 8; [165; 170): 5. Tính trung vị (cm).","a":"159","g":"Mₑ = 155 + (15 − 5)/12·5 ≈ 159,2.","r":"Làm tròn đến hàng đơn vị"}]}]},{"id":"11-IV","so":"IV","ten":"Quan hệ song song trong không gian","hk":1,"lessons":[{"id":"11-IV-10","ten":"Bài 10. Đường thẳng và mặt phẳng trong không gian","ycc":["Nhận biết các quan hệ liên thuộc cơ bản giữa điểm, đường thẳng, mặt phẳng.","Xác định giao tuyến của hai mặt phẳng, giao điểm của đường thẳng và mặt phẳng; nhận biết hình chóp, hình tứ diện."],"kt":["Một mặt phẳng được xác định bởi: ba điểm không thẳng hàng; một đường thẳng và một điểm nằm ngoài nó; hai đường thẳng cắt nhau.","Hai mặt phẳng phân biệt có một điểm chung thì có một đường thẳng chung (giao tuyến).","Tìm giao tuyến: tìm hai điểm chung của hai mặt phẳng.","Tìm giao điểm của d và (P): tìm một đường thẳng trong (P) cắt d."],"d":{"t":"mc","q":"Qua ba điểm không thẳng hàng xác định được bao nhiêu mặt phẳng?","o":["3","Vô số","2","1"],"g":"Tính chất thừa nhận.","a":3},"ex":[{"t":"mc","q":"Hình chóp tứ giác có bao nhiêu mặt?","o":["5","8","6","4"],"g":"4 mặt bên và 1 mặt đáy.","a":0},{"t":"mc","q":"Hình chóp S.ABCD có O là giao điểm của AC và BD. Giao tuyến của (SAC) và (SBD) là","o":["SA","BD","AC","SO"],"g":"S và O là hai điểm chung.","a":3},{"t":"tf","q":"Cho tứ diện ABCD.","s":[["Tứ diện có 4 mặt",true],["Tứ diện có 6 cạnh",true],["Bốn điểm A, B, C, D cùng thuộc một mặt phẳng",false],["Mỗi mặt của tứ diện là một tam giác",true]],"g":"Bốn đỉnh tứ diện không đồng phẳng."},{"t":"sa","q":"Hình chóp có đáy là ngũ giác có bao nhiêu cạnh?","a":"10","g":"5 cạnh đáy và 5 cạnh bên.","r":""},{"t":"sa","q":"Có bao nhiêu mặt phẳng phân biệt đi qua ba trong bốn đỉnh của một tứ diện?","a":"4","g":"C₄³ = 4.","r":""}]},{"id":"11-IV-11","ten":"Bài 11. Hai đường thẳng song song","ycc":["Nhận biết vị trí tương đối của hai đường thẳng trong không gian: trùng, song song, cắt nhau, chéo nhau.","Vận dụng tính chất về giao tuyến của ba mặt phẳng."],"kt":["Hai đường thẳng chéo nhau: không cùng nằm trong một mặt phẳng.","Hai đường thẳng song song: cùng nằm trong một mặt phẳng và không có điểm chung.","Hai mặt phẳng phân biệt lần lượt chứa hai đường thẳng song song thì giao tuyến (nếu có) song song hoặc trùng với một trong hai đường thẳng đó.","Đường trung bình của tam giác song song và bằng nửa cạnh đáy."],"d":{"t":"mc","q":"Hai đường thẳng không có điểm chung và không cùng nằm trong một mặt phẳng thì","o":["Chéo nhau","Song song","Trùng nhau","Cắt nhau"],"g":"Định nghĩa.","a":0},"ex":[{"t":"mc","q":"Hình chóp S.ABCD có đáy là hình bình hành. Giao tuyến của (SAB) và (SCD) là đường thẳng qua S và song song với","o":["BC","AC","AB","SD"],"g":"AB // CD.","a":2},{"t":"mc","q":"Trong tứ diện ABCD, hai đường thẳng AB và CD","o":["Song song","Cắt nhau","Chéo nhau","Trùng nhau"],"g":"Không đồng phẳng.","a":2},{"t":"tf","q":"Cho tứ diện ABCD, M và N là trung điểm của AB và AC.","s":[["MN // BC",true],["MN = BC/2",true],["MN và CD chéo nhau",true],["MN cắt BD",false]],"g":"MN nằm trong (ABC), BD cắt (ABC) tại B không thuộc MN."},{"t":"sa","q":"Tứ diện đều ABCD cạnh 6, M và N là trung điểm AB, AC. Tính MN.","a":"3","g":"Đường trung bình.","r":""},{"t":"sa","q":"Trong hình hộp, có bao nhiêu cạnh song song với một cạnh cho trước (không kể cạnh đó)?","a":"3","g":"12 cạnh chia thành 3 nhóm, mỗi nhóm 4 cạnh song song.","r":""}]},{"id":"11-IV-12","ten":"Bài 12. Đường thẳng và mặt phẳng song song","ycc":["Nhận biết đường thẳng song song với mặt phẳng; điều kiện và tính chất."],"kt":["d // (P) nếu d không nằm trong (P) và d song song với một đường thẳng nằm trong (P).","Nếu d // (P) và (Q) chứa d cắt (P) theo giao tuyến a thì a // d.","Hai mặt phẳng cắt nhau cùng song song với d thì giao tuyến song song với d."],"d":{"t":"mc","q":"Đường thẳng d song song với mặt phẳng (P) nếu","o":["d vuông góc với một đường thẳng trong (P)","d cắt (P)","d song song với một đường thẳng bất kỳ","d không nằm trong (P) và song song với một đường thẳng nằm trong (P)"],"g":"Điều kiện đủ.","a":3},"ex":[{"t":"mc","q":"Hình chóp S.ABCD đáy là hình bình hành. Đường thẳng AB song song với mặt phẳng","o":["(SCD)","(ABCD)","(SAB)","(SAC)"],"g":"AB // CD ⊂ (SCD).","a":0},{"t":"mc","q":"Hình chóp S.ABCD, M và N là trung điểm SA, SB. Đường thẳng MN song song với","o":["(ABCD)","(SAD)","(SBC)","(SAB)"],"g":"MN // AB ⊂ (ABCD).","a":0},{"t":"tf","q":"Hình chóp S.ABCD đáy là hình bình hành, M là trung điểm SA, mặt phẳng (MBC) cắt SD tại N.","s":[["BC // (SAD)",true],["MN // AD",true],["N là trung điểm SD",true],["MN = AD",false]],"g":"MN là đường trung bình của tam giác SAD nên MN = AD/2."},{"t":"sa","q":"Tứ diện SABC, M thuộc SA với SM = 2MA. Mặt phẳng qua M song song với (ABC) cắt SB tại N. Tính tỉ số SN/SB.","a":"0,67","g":"MN // AB nên SN/SB = SM/SA = 2/3.","r":"Làm tròn đến hàng phần trăm"},{"t":"sa","q":"Hình chóp S.ABCD đáy là hình bình hành có AD = 8, M là trung điểm SA, mặt phẳng (MBC) cắt SD tại N. Tính MN.","a":"4","g":"BC // AD nên MN // AD, N là trung điểm SD; MN = AD/2.","r":""}]},{"id":"11-IV-13","ten":"Bài 13. Hai mặt phẳng song song","ycc":["Nhận biết hai mặt phẳng song song; điều kiện, tính chất; định lí Thalès trong không gian.","Nhận biết hình lăng trụ, hình hộp."],"kt":["(P) // (Q) nếu (P) chứa hai đường thẳng cắt nhau cùng song song với (Q).","Hai mặt phẳng song song bị mặt phẳng thứ ba cắt theo hai giao tuyến song song.","Định lí Thalès: ba mặt phẳng song song chắn trên hai cát tuyến những đoạn tương ứng tỉ lệ.","Hình lăng trụ có các mặt bên là hình bình hành; hình hộp có 6 mặt là hình bình hành."],"d":{"t":"mc","q":"Hai mặt phẳng (P) và (Q) song song nếu","o":["(P) chứa hai đường thẳng song song với (Q)","(P) chứa một đường thẳng song song với (Q)","(P) chứa hai đường thẳng cắt nhau cùng song song với (Q)","(P) và (Q) không có điểm chung với một đường thẳng"],"g":"Điều kiện cần hai đường thẳng cắt nhau.","a":2},"ex":[{"t":"mc","q":"Hình hộp có bao nhiêu cặp mặt song song?","o":["6","2","4","3"],"g":"6 mặt chia thành 3 cặp.","a":3},{"t":"mc","q":"Các mặt bên của hình lăng trụ là","o":["Hình thang cân","Tam giác","Hình bình hành","Hình vuông"],"g":"Tính chất lăng trụ.","a":2},{"t":"tf","q":"Cho hình hộp ABCD.A'B'C'D'.","s":[["(ABCD) // (A'B'C'D')",true],["(ABB'A') // (DCC'D')",true],["AA' = CC'",true],["(ACC'A') // (BDD'B')",false]],"g":"(ACC'A') và (BDD'B') cắt nhau."},{"t":"sa","q":"Hình hộp có bao nhiêu mặt?","a":"6","g":"Ba cặp mặt đối diện.","r":""},{"t":"sa","q":"Ba mặt phẳng song song cắt d₁ tại A, B, C và cắt d₂ tại A', B', C'. Biết AB = 2, BC = 3, A'B' = 4. Tính B'C'.","a":"6","g":"AB/BC = A'B'/B'C'.","r":""}]},{"id":"11-IV-14","ten":"Bài 14. Phép chiếu song song","ycc":["Nhận biết phép chiếu song song và các tính chất cơ bản.","Vẽ hình biểu diễn của một hình không gian."],"kt":["Phép chiếu song song biến đường thẳng thành đường thẳng, biến đoạn thẳng thành đoạn thẳng (khi không cùng phương chiếu).","Bảo toàn tính song song, tính thẳng hàng và thứ tự điểm, tỉ số độ dài hai đoạn thẳng cùng phương.","Không bảo toàn độ dài và độ lớn góc.","Biến trung điểm thành trung điểm, trọng tâm thành trọng tâm."],"d":{"t":"mc","q":"Phép chiếu song song biến trung điểm của đoạn thẳng thành","o":["Một đầu mút","Điểm bất kỳ","Trung điểm của hình chiếu","Không xác định"],"g":"Bảo toàn tỉ số.","a":2},"ex":[{"t":"mc","q":"Phép chiếu song song không bảo toàn yếu tố nào?","o":["Tỉ số hai đoạn thẳng cùng phương","Độ lớn góc","Tính song song","Tính thẳng hàng"],"g":"Góc có thể thay đổi.","a":1},{"t":"mc","q":"Hình biểu diễn của một hình vuông có thể là","o":["Tam giác","Hình bình hành","Hình tròn","Ngũ giác"],"g":"Bảo toàn song song.","a":1},{"t":"tf","q":"Xét một phép chiếu song song.","s":[["Biến hai đường thẳng song song thành hai đường thẳng song song hoặc trùng nhau",true],["Giữ nguyên tỉ số hai đoạn thẳng cùng phương",true],["Biến tam giác đều thành tam giác đều",false],["Biến trung điểm thành trung điểm",true]],"g":"Góc không bảo toàn nên tam giác đều có thể thành tam giác thường."},{"t":"sa","q":"Điểm M thuộc đoạn AB với AM/AB = 1/4. Qua phép chiếu song song, ảnh của AB là A'B' = 8. Tính A'M'.","a":"2","g":"Bảo toàn tỉ số: A'M' = 8/4.","r":""},{"t":"sa","q":"Trong hình biểu diễn của tam giác ABC, G' là ảnh của trọng tâm, M' là ảnh trung điểm BC. Tính tỉ số A'G'/A'M'.","a":"0,67","g":"Bằng 2/3 như ban đầu.","r":"Làm tròn đến hàng phần trăm"}]}]},{"id":"11-V","so":"V","ten":"Giới hạn. Hàm số liên tục","hk":1,"lessons":[{"id":"11-V-15","ten":"Bài 15. Giới hạn của dãy số","ycc":["Nhận biết giới hạn hữu hạn, vô cực của dãy số; tính giới hạn bằng các quy tắc.","Tính tổng cấp số nhân lùi vô hạn."],"kt":["lim 1/n = 0; lim 1/nᵏ = 0 (k > 0); lim qⁿ = 0 khi |q| < 1.","Giới hạn phân thức: chia tử và mẫu cho lũy thừa bậc cao nhất của n.","Cấp số nhân lùi vô hạn (|q| < 1): S = u₁/(1 − q)."],"d":{"t":"mc","q":"lim 1/n bằng","o":["+∞","1","Không tồn tại","0"],"g":"Giới hạn cơ bản.","a":3},"ex":[{"t":"mc","q":"lim (2n + 1)/(n − 3) bằng","o":["2","+∞","−1/3","1"],"g":"Chia tử và mẫu cho n.","a":0},{"t":"mc","q":"lim (1/2)ⁿ bằng","o":["0","+∞","1/2","1"],"g":"|q| < 1.","a":0},{"t":"tf","q":"Xét tổng S = 1 + 1/3 + 1/9 + …","s":[["Đây là cấp số nhân có q = 1/3",true],["|q| < 1 nên là cấp số nhân lùi vô hạn",true],["S = 3/2",true],["S = 2",false]],"g":"S = 1/(1 − 1/3) = 3/2."},{"t":"sa","q":"Tính lim (3n² − 1)/(n² + 2).","a":"3","g":"Chia cho n².","r":""},{"t":"sa","q":"Tính tổng 4 + 2 + 1 + 1/2 + …","a":"8","g":"S = 4/(1 − 1/2).","r":""}]},{"id":"11-V-16","ten":"Bài 16. Giới hạn của hàm số","ycc":["Nhận biết giới hạn hữu hạn, giới hạn một phía, giới hạn tại vô cực và giới hạn vô cực của hàm số.","Tính giới hạn dạng 0/0, ∞/∞ đơn giản."],"kt":["Hàm đa thức, phân thức (xác định tại x₀): lim f(x) = f(x₀).","Dạng 0/0: phân tích nhân tử hoặc nhân liên hợp để rút gọn.","Tại vô cực: chia tử và mẫu cho lũy thừa cao nhất của x.","lim f(x) = L tại x₀ ⇔ giới hạn trái = giới hạn phải = L."],"d":{"t":"mc","q":"lim (x² − 4)/(x − 2) khi x → 2 bằng","o":["4","0","2","Không tồn tại"],"g":"Rút gọn thành x + 2.","a":0},"ex":[{"t":"mc","q":"lim (2x − 1)/(x + 1) khi x → +∞ bằng","o":["1","−1","2","+∞"],"g":"Chia cho x.","a":2},{"t":"mc","q":"lim 1/(x − 1) khi x → 1⁺ bằng","o":["1","+∞","0","−∞"],"g":"Mẫu dương tiến về 0.","a":1},{"t":"tf","q":"Cho f(x) = (x² − 1)/(x − 1).","s":[["f không xác định tại x = 1",true],["lim f(x) khi x → 1 bằng 2",true],["lim f(x) khi x → 0 bằng 1",true],["lim f(x) khi x → +∞ bằng 1",false]],"g":"f(x) = x + 1 (x ≠ 1) nên tiến tới +∞."},{"t":"sa","q":"Tính lim (x² − 9)/(x − 3) khi x → 3.","a":"6","g":"x + 3 → 6.","r":""},{"t":"sa","q":"Tính lim (√(x + 4) − 2)/x khi x → 0.","a":"0,25","g":"Nhân liên hợp: 1/(√(x + 4) + 2) → 1/4.","r":""}]},{"id":"11-V-17","ten":"Bài 17. Hàm số liên tục","ycc":["Nhận biết hàm số liên tục tại một điểm, trên một khoảng, đoạn; tính liên tục của các hàm sơ cấp.","Vận dụng tính liên tục để chứng minh phương trình có nghiệm."],"kt":["f liên tục tại x₀ ⇔ lim f(x) khi x → x₀ = f(x₀).","Hàm đa thức liên tục trên ℝ; phân thức, căn thức, lượng giác liên tục trên từng khoảng xác định.","f liên tục trên [a; b] và f(a)·f(b) < 0 thì f(x) = 0 có ít nhất một nghiệm trong (a; b)."],"d":{"t":"mc","q":"Hàm đa thức","o":["Chỉ liên tục tại x = 0","Liên tục trên (0; +∞)","Liên tục trên ℝ","Không liên tục"],"g":"Tính chất.","a":2},"ex":[{"t":"mc","q":"Hàm số y = 1/(x − 1) liên tục trên","o":["ℝ","(−∞; 1) và (1; +∞)","[1; +∞)","(−∞; 1]"],"g":"Tập xác định gồm hai khoảng.","a":1},{"t":"mc","q":"Nếu f liên tục trên [a; b] và f(a)·f(b) < 0 thì","o":["f đồng biến","f(a) = f(b)","f(x) = 0 vô nghiệm","f(x) = 0 có ít nhất một nghiệm trong (a; b)"],"g":"Định lí giá trị trung gian.","a":3},{"t":"tf","q":"Cho f(x) = x² + 1 khi x ≥ 1 và f(x) = 2x + m khi x < 1.","s":[["f(1) = 2",true],["Giới hạn phải tại x = 1 bằng 2",true],["Giới hạn trái tại x = 1 bằng 2 + m",true],["f liên tục tại x = 1 khi m = 1",false]],"g":"Cần 2 + m = 2 ⇒ m = 0."},{"t":"sa","q":"Cho f(x) = x² + 1 khi x ≥ 1 và f(x) = 2x + m khi x < 1. Tìm m để f liên tục tại x = 1.","a":"0","g":"2 + m = 2.","r":""},{"t":"sa","q":"Cho f(x) = (x² − 4)/(x − 2) khi x ≠ 2 và f(2) = a. Tìm a để f liên tục tại x = 2.","a":"4","g":"lim = 4.","r":""}]}]},{"id":"11-VI","so":"VI","ten":"Hàm số mũ và hàm số lôgarit","hk":2,"lessons":[{"id":"11-VI-18","ten":"Bài 18. Lũy thừa với số mũ thực","ycc":["Nhận biết lũy thừa với số mũ nguyên, hữu tỉ, thực; vận dụng tính chất của phép tính lũy thừa.","Giải bài toán thực tế liên quan lãi kép, tăng trưởng."],"kt":["a⁰ = 1; a⁻ⁿ = 1/aⁿ (a ≠ 0); a^(m/n) = ⁿ√(aᵐ) (a > 0).","aᵐ·aⁿ = aᵐ⁺ⁿ; aᵐ/aⁿ = aᵐ⁻ⁿ; (aᵐ)ⁿ = aᵐⁿ; (ab)ⁿ = aⁿbⁿ.","a > 1: aᵐ > aⁿ ⇔ m > n; 0 < a < 1: aᵐ > aⁿ ⇔ m < n.","Lãi kép: số tiền sau n kì A(1 + r)ⁿ."],"d":{"t":"mc","q":"2³·2⁴ bằng","o":["2¹","2¹²","4⁷","2⁷"],"g":"aᵐ·aⁿ = aᵐ⁺ⁿ.","a":3},"ex":[{"t":"mc","q":"Giá trị của 8^(2/3) là","o":["16/3","4","2","64"],"g":"(∛8)² = 4.","a":1},{"t":"mc","q":"Với a > 0, (aᵐ)ⁿ bằng","o":["aᵐ⁻ⁿ","aⁿᵐ⁺¹","aᵐⁿ","aᵐ⁺ⁿ"],"g":"Tính chất lũy thừa.","a":2},{"t":"tf","q":"Cho a > 0.","s":[["a⁰ = 1",true],["a⁻² = 1/a²",true],["a^(1/2) = √a",true],["aᵐ·aⁿ = aᵐⁿ",false]],"g":"aᵐ·aⁿ = aᵐ⁺ⁿ."},{"t":"sa","q":"Tính 27^(1/3) + 16^(1/2).","a":"7","g":"3 + 4.","r":""},{"t":"sa","q":"Gửi 100 triệu đồng, lãi kép 6%/năm. Sau 2 năm có bao nhiêu triệu đồng?","a":"112","g":"100·1,06² = 112,36.","r":"Làm tròn đến hàng đơn vị"}]},{"id":"11-VI-19","ten":"Bài 19. Lôgarit","ycc":["Nhận biết khái niệm lôgarit; tính lôgarit bằng định nghĩa, tính chất và máy tính cầm tay.","Vận dụng lôgarit trong một số bài toán thực tế (độ pH, độ lớn động đất…)."],"kt":["log_a b = α ⇔ a^α = b (a > 0, a ≠ 1, b > 0).","log_a 1 = 0; log_a a = 1; log_a(bc) = log_a b + log_a c; log_a(b/c) = log_a b − log_a c; log_a bⁿ = n·log_a b.","Đổi cơ số: log_a b = log_c b / log_c a.","log b là lôgarit thập phân (cơ số 10); ln b là lôgarit tự nhiên (cơ số e)."],"d":{"t":"mc","q":"log₂ 8 bằng","o":["16","3","4","2"],"g":"2³ = 8.","a":1},"ex":[{"t":"mc","q":"Với a, b > 0, log(ab) bằng","o":["log a − log b","log a + log b","log a · log b","a·log b"],"g":"Tính chất.","a":1},{"t":"mc","q":"log₃ 81 bằng","o":["9","27","4","3"],"g":"3⁴ = 81.","a":2},{"t":"tf","q":"Xét các đẳng thức sau.","s":[["log₂ 1 = 0",true],["log 100 = 2",true],["ln e = 1",true],["log₂(8/2) = log₂ 8 / log₂ 2",false]],"g":"log₂(8/2) = log₂ 8 − log₂ 2 = 2."},{"t":"sa","q":"Tính log₂ 64 − log₂ 4.","a":"4","g":"6 − 2.","r":""},{"t":"sa","q":"Độ pH = −log[H⁺]. Dung dịch có [H⁺] = 10⁻³ mol/L có độ pH bằng bao nhiêu?","a":"3","g":"−log 10⁻³ = 3.","r":""}]},{"id":"11-VI-20","ten":"Bài 20. Hàm số mũ và hàm số lôgarit","ycc":["Nhận biết hàm số mũ, hàm số lôgarit; tập xác định, tính đồng biến, nghịch biến, đồ thị.","Giải bài toán thực tế liên quan (tăng trưởng, phân rã)."],"kt":["y = aˣ (a > 0, a ≠ 1): tập xác định ℝ, tập giá trị (0; +∞), đồ thị qua (0; 1).","y = log_a x: tập xác định (0; +∞), đồ thị qua (1; 0).","a > 1: hai hàm đồng biến; 0 < a < 1: hai hàm nghịch biến.","y = log_a u(x) xác định khi u(x) > 0."],"d":{"t":"mc","q":"Hàm số y = 2ˣ","o":["Có tập xác định (0; +∞)","Nghịch biến trên ℝ","Đồng biến trên ℝ","Có đồ thị qua (1; 0)"],"g":"a = 2 > 1.","a":2},"ex":[{"t":"mc","q":"Tập xác định của hàm số y = log₂(x − 1) là","o":["(0; +∞)","ℝ","(1; +∞)","[1; +∞)"],"g":"x − 1 > 0.","a":2},{"t":"mc","q":"Hàm số y = (1/2)ˣ","o":["Nghịch biến trên ℝ","Có giá trị âm","Có tập xác định (0; +∞)","Đồng biến trên ℝ"],"g":"0 < a < 1.","a":0},{"t":"tf","q":"Cho hàm số y = log₃ x.","s":[["Tập xác định là (0; +∞)",true],["Hàm số đồng biến",true],["Đồ thị đi qua (1; 0)",true],["Đồ thị đi qua (3; 0)",false]],"g":"log₃ 3 = 1 nên đồ thị qua (3; 1)."},{"t":"sa","q":"Số vi khuẩn N(t) = 100·2ᵗ (t tính bằng giờ). Sau 3 giờ có bao nhiêu vi khuẩn?","a":"800","g":"100·8.","r":""},{"t":"sa","q":"Cho y = 3ˣ. Tính y tại x = 2.","a":"9","g":"3² = 9.","r":""}]},{"id":"11-VI-21","ten":"Bài 21. Phương trình, bất phương trình mũ và lôgarit","ycc":["Giải phương trình, bất phương trình mũ và lôgarit ở dạng đơn giản.","Giải bài toán thực tế dẫn đến phương trình, bất phương trình mũ, lôgarit."],"kt":["aˣ = b (b > 0) ⇔ x = log_a b; log_a x = b ⇔ x = aᵇ.","Đưa về cùng cơ số: a^f(x) = a^g(x) ⇔ f(x) = g(x).","Bất phương trình: a > 1 giữ chiều; 0 < a < 1 đổi chiều. Với lôgarit nhớ điều kiện biểu thức dưới log dương.","Đặt ẩn phụ t = aˣ > 0 để đưa về phương trình bậc hai."],"d":{"t":"mc","q":"Phương trình 2ˣ = 8 có nghiệm","o":["x = 3","x = 1/3","x = 2","x = 4"],"g":"2³ = 8.","a":0},"ex":[{"t":"mc","q":"log₂ x = 3 khi và chỉ khi","o":["x = 8","x = 9","x = 6","x = 3/2"],"g":"x = 2³.","a":0},{"t":"mc","q":"Tập nghiệm của 3ˣ > 9 là","o":["x < 2","x > 1","x > 3","x > 2"],"g":"3ˣ > 3².","a":3},{"t":"tf","q":"Xét phương trình 4ˣ − 3·2ˣ + 2 = 0.","s":[["Đặt t = 2ˣ với t > 0",true],["Được phương trình t² − 3t + 2 = 0",true],["Phương trình có nghiệm x = 0 và x = 1",true],["Tổng các nghiệm bằng 3",false]],"g":"t = 1 hoặc t = 2 ⇒ x = 0 hoặc x = 1; tổng bằng 1."},{"t":"sa","q":"Giải phương trình log₃(x + 1) = 2.","a":"8","g":"x + 1 = 9.","r":""},{"t":"sa","q":"Bất phương trình log₂ x < 3 có bao nhiêu nghiệm nguyên?","a":"7","g":"0 < x < 8.","r":""}]}]},{"id":"11-VII","so":"VII","ten":"Quan hệ vuông góc trong không gian","hk":2,"lessons":[{"id":"11-VII-22","ten":"Bài 22. Hai đường thẳng vuông góc","ycc":["Nhận biết góc giữa hai đường thẳng; hai đường thẳng vuông góc."],"kt":["Góc giữa a và b là góc giữa a' và b' cùng đi qua một điểm, lần lượt song song (hoặc trùng) với a và b.","Góc giữa hai đường thẳng nằm trong đoạn [0°; 90°].","a ⊥ b ⇔ góc giữa chúng bằng 90°.","Nếu a // b và c ⊥ a thì c ⊥ b."],"d":{"t":"mc","q":"Góc giữa hai đường thẳng có số đo trong khoảng","o":["[0°; 90°]","[0°; 180°]","[0°; 360°)","(0°; 90°)"],"g":"Định nghĩa.","a":0},"ex":[{"t":"mc","q":"Hình lập phương ABCD.A'B'C'D'. Góc giữa AB và B'C' là","o":["90°","45°","60°","0°"],"g":"B'C' // BC ⊥ AB.","a":0},{"t":"mc","q":"Hình lập phương ABCD.A'B'C'D'. Góc giữa AC và A'D' là","o":["30°","60°","45°","90°"],"g":"A'D' // AD; góc CAD = 45°.","a":2},{"t":"tf","q":"Cho hình lập phương ABCD.A'B'C'D'.","s":[["AB ⊥ CC'",true],["Góc giữa AB và C'D' bằng 0°",true],["Góc giữa AC và B'D' bằng 90°",true],["Góc giữa AA' và BD bằng 45°",false]],"g":"AA' vuông góc với mặt đáy nên vuông góc BD."},{"t":"sa","q":"Tứ diện đều ABCD. Góc giữa AB và CD bằng bao nhiêu độ?","a":"90","g":"Gọi M trung điểm CD: CD ⊥ (ABM).","r":""},{"t":"sa","q":"Hình lập phương ABCD.A'B'C'D'. Góc giữa A'C' và BC' bằng bao nhiêu độ?","a":"60","g":"Tam giác A'BC' đều (ba đường chéo mặt).","r":""}]},{"id":"11-VII-23","ten":"Bài 23. Đường thẳng vuông góc với mặt phẳng","ycc":["Nhận biết đường thẳng vuông góc với mặt phẳng; điều kiện và tính chất."],"kt":["d ⊥ (P) nếu d vuông góc với hai đường thẳng cắt nhau nằm trong (P).","d ⊥ (P) thì d vuông góc với mọi đường thẳng nằm trong (P).","Hình chóp S.ABCD đáy hình vuông, SA ⊥ (ABCD): BC ⊥ (SAB), CD ⊥ (SAD), BD ⊥ (SAC).","Định lí ba đường vuông góc: a ⊂ (P), b có hình chiếu b' trên (P): a ⊥ b ⇔ a ⊥ b'."],"d":{"t":"mc","q":"Đường thẳng d vuông góc với mặt phẳng (P) nếu d","o":["Vuông góc với hai đường thẳng song song trong (P)","Vuông góc với một đường thẳng trong (P)","Song song với (P)","Vuông góc với hai đường thẳng cắt nhau trong (P)"],"g":"Điều kiện.","a":3},"ex":[{"t":"mc","q":"Hình chóp S.ABCD đáy hình vuông, SA ⊥ (ABCD). Đường thẳng BC vuông góc với mặt phẳng","o":["(SBD)","(SCD)","(SAB)","(SAC)"],"g":"BC ⊥ AB và BC ⊥ SA.","a":2},{"t":"mc","q":"Nếu SA ⊥ (ABC) thì","o":["SA cắt BC","SB ⊥ BC luôn đúng","SA // BC","SA ⊥ BC"],"g":"SA vuông góc mọi đường trong (ABC).","a":3},{"t":"tf","q":"Hình chóp S.ABCD đáy hình vuông, SA ⊥ (ABCD).","s":[["SA ⊥ BD",true],["BD ⊥ (SAC)",true],["CD ⊥ (SAD)",true],["SC ⊥ (ABCD)",false]],"g":"Chỉ SA vuông góc với đáy."},{"t":"sa","q":"SA ⊥ (ABC), SA = 3, AB = 4. Tính SB.","a":"5","g":"Tam giác SAB vuông tại A.","r":""},{"t":"sa","q":"Hình lập phương cạnh 2. Tính độ dài đường chéo AC'.","a":"3,46","g":"2√3 ≈ 3,46.","r":"Làm tròn đến hàng phần trăm"}]},{"id":"11-VII-24","ten":"Bài 24. Phép chiếu vuông góc. Góc giữa đường thẳng và mặt phẳng","ycc":["Nhận biết phép chiếu vuông góc; xác định góc giữa đường thẳng và mặt phẳng."],"kt":["Góc giữa d và (P) là góc giữa d và hình chiếu d' của nó trên (P) (khi d không vuông góc với (P)).","Nếu SA ⊥ (P) và B ∈ (P) thì góc giữa SB và (P) là góc SBA.","Góc giữa đường thẳng và mặt phẳng thuộc [0°; 90°]."],"d":{"t":"mc","q":"Hình chóp S.ABCD có SA ⊥ (ABCD). Góc giữa SC và (ABCD) là","o":["Góc ASC","Góc SCB","Góc SAC","Góc SCA"],"g":"AC là hình chiếu của SC.","a":3},"ex":[{"t":"mc","q":"SA ⊥ (ABCD). Hình chiếu vuông góc của S trên (ABCD) là","o":["A","Tâm đáy","C","B"],"g":"Chân đường vuông góc.","a":0},{"t":"mc","q":"Hình chóp S.ABCD đáy hình vuông cạnh a, SA ⊥ đáy, SA = a√2. Góc giữa SC và đáy là","o":["90°","45°","60°","30°"],"g":"AC = a√2 = SA.","a":1},{"t":"tf","q":"Hình chóp S.ABC có SA ⊥ (ABC), SA = AB = 2.","s":[["Hình chiếu của SB trên (ABC) là AB",true],["Góc giữa SB và (ABC) là góc SBA",true],["Góc đó bằng 45°",true],["tan của góc đó bằng 2",false]],"g":"tan = SA/AB = 1."},{"t":"sa","q":"Hình lập phương ABCD.A'B'C'D'. Góc giữa AC' và (ABCD) bằng bao nhiêu độ?","a":"35","g":"tan = CC'/AC = 1/√2, góc ≈ 35,26°.","r":"Làm tròn đến hàng đơn vị"},{"t":"sa","q":"SA ⊥ (ABC), SA = 1, AB = √3. Góc giữa SB và (ABC) bằng bao nhiêu độ?","a":"30","g":"tan = 1/√3.","r":""}]},{"id":"11-VII-25","ten":"Bài 25. Hai mặt phẳng vuông góc","ycc":["Nhận biết góc giữa hai mặt phẳng, góc nhị diện, hai mặt phẳng vuông góc; hình lăng trụ đứng, hình chóp đều."],"kt":["(P) ⊥ (Q) nếu (P) chứa một đường thẳng vuông góc với (Q).","Góc nhị diện [S, CD, A]: lấy đường thẳng trong mỗi mặt cùng vuông góc với cạnh CD tại một điểm.","Lăng trụ đứng có cạnh bên vuông góc với đáy; hình chóp đều có đáy là đa giác đều và chân đường cao trùng tâm đáy."],"d":{"t":"mc","q":"Mặt phẳng (P) vuông góc với (Q) nếu","o":["(P) và (Q) không có điểm chung","(P) cắt (Q)","(P) chứa một đường thẳng song song với (Q)","(P) chứa một đường thẳng vuông góc với (Q)"],"g":"Điều kiện.","a":3},"ex":[{"t":"mc","q":"Nếu SA ⊥ (ABCD) thì mặt phẳng nào vuông góc với (ABCD)?","o":["(SBD)","(SAB)","(SBC)","(SCD)"],"g":"(SAB) chứa SA.","a":1},{"t":"mc","q":"Hình chóp đều là hình chóp có","o":["Đáy là đa giác đều và chân đường cao trùng tâm đáy","Đáy là hình vuông","Các cạnh bên vuông góc với đáy","Tất cả các mặt là tam giác đều"],"g":"Định nghĩa.","a":0},{"t":"tf","q":"Hình chóp S.ABCD đáy hình vuông cạnh 2, SA ⊥ (ABCD), SA = 2.","s":[["(SAD) ⊥ (ABCD)",true],["(SAB) ⊥ (SAD)",true],["Góc nhị diện [S, CD, A] có góc phẳng là góc SDA",true],["Góc đó bằng 60°",false]],"g":"tan SDA = SA/AD = 1 nên bằng 45°."},{"t":"sa","q":"Hình chóp S.ABCD đáy hình vuông cạnh 2, SA ⊥ (ABCD), SA = 2√3. Góc giữa (SBC) và (ABCD) bằng bao nhiêu độ?","a":"60","g":"Góc SBA, tan = 2√3/2 = √3.","r":""},{"t":"sa","q":"Lăng trụ đứng tam giác đều có cạnh đáy 2, cạnh bên 3. Tính diện tích xung quanh.","a":"18","g":"3 mặt bên hình chữ nhật 2 × 3.","r":""}]},{"id":"11-VII-26","ten":"Bài 26. Khoảng cách","ycc":["Xác định khoảng cách từ điểm đến đường thẳng, đến mặt phẳng; giữa đường thẳng và mặt phẳng song song, giữa hai mặt phẳng song song; giữa hai đường thẳng chéo nhau (trường hợp đơn giản)."],"kt":["d(M, (P)) = MH với H là hình chiếu vuông góc của M trên (P).","SA ⊥ (ABC), AB ⊥ BC: d(A, (SBC)) = AH, với AH ⊥ SB; AH = SA·AB / √(SA² + AB²).","d(a, (P)) với a // (P) bằng khoảng cách từ một điểm bất kỳ trên a đến (P).","Khoảng cách giữa hai đường chéo nhau là độ dài đoạn vuông góc chung."],"d":{"t":"mc","q":"Hình chóp S.ABCD có SA ⊥ (ABCD). Khoảng cách từ S đến (ABCD) là","o":["SB","AC","SC","SA"],"g":"A là hình chiếu của S.","a":3},"ex":[{"t":"mc","q":"Hình lập phương cạnh a. Khoảng cách giữa hai mặt (ABCD) và (A'B'C'D') là","o":["a√3","a/2","a√2","a"],"g":"Bằng cạnh bên.","a":3},{"t":"mc","q":"SA ⊥ (ABC), AB ⊥ BC. Khoảng cách từ A đến (SBC) là độ dài đoạn","o":["AC","AH với H là hình chiếu của A trên SB","SA","AB"],"g":"BC ⊥ (SAB) nên (SBC) ⊥ (SAB).","a":1},{"t":"tf","q":"Hình lập phương ABCD.A'B'C'D' cạnh 2.","s":[["d(A, (A'B'C'D')) = 2",true],["Khoảng cách giữa AA' và CC' bằng 2√2",true],["Khoảng cách giữa AB và CC' bằng 2",true],["d(A, (BCC'B')) = 2√2",false]],"g":"d(A, (BCC'B')) = AB = 2."},{"t":"sa","q":"SA ⊥ (ABC), SA = AB = 2, AB ⊥ BC. Tính d(A, (SBC)).","a":"1,41","g":"AH = SA·AB/SB = 4/(2√2) = √2.","r":"Làm tròn đến hàng phần trăm"},{"t":"sa","q":"Hình lập phương ABCD.A'B'C'D' cạnh 3. Tính d(A, (BDD'B')).","a":"2,12","g":"Bằng nửa đường chéo đáy: 3√2/2.","r":"Làm tròn đến hàng phần trăm"}]},{"id":"11-VII-27","ten":"Bài 27. Thể tích","ycc":["Tính thể tích khối chóp, khối lăng trụ, khối hộp, khối chóp cụt đều; vận dụng vào thực tế."],"kt":["Khối chóp: V = ⅓·B·h. Khối lăng trụ: V = B·h. Khối hộp chữ nhật: V = abc.","Khối chóp cụt đều: V = ⅓·h·(S + S' + √(S·S')).","B là diện tích đáy, h là chiều cao."],"d":{"t":"mc","q":"Thể tích khối chóp có diện tích đáy B và chiều cao h là","o":["3Bh","Bh","½Bh","⅓Bh"],"g":"Công thức.","a":3},"ex":[{"t":"mc","q":"Khối lăng trụ có diện tích đáy 6 và chiều cao 4 có thể tích là","o":["10","8","12","24"],"g":"V = 6·4.","a":3},{"t":"mc","q":"Khối chóp tứ giác đều có cạnh đáy 2 và chiều cao 3 có thể tích là","o":["12","2","4","6"],"g":"⅓·4·3.","a":2},{"t":"tf","q":"Hình hộp chữ nhật có ba kích thước 2, 3, 4.","s":[["Thể tích bằng 24",true],["Đường chéo bằng √29",true],["Diện tích toàn phần bằng 52",true],["Khối tứ diện cắt ra tại một đỉnh (ba cạnh 2, 3, 4) có thể tích 8",false]],"g":"Tứ diện vuông có V = ⅙·2·3·4 = 4."},{"t":"sa","q":"Hình chóp S.ABC có SA ⊥ (ABC), SA = 3, tam giác ABC vuông cân tại B với AB = BC = 2. Tính thể tích.","a":"2","g":"V = ⅓·(½·2·2)·3.","r":""},{"t":"sa","q":"Khối chóp cụt đều có chiều cao 3, diện tích hai đáy 16 và 4. Tính thể tích.","a":"28","g":"⅓·3·(16 + 4 + 8).","r":""}]}]},{"id":"11-VIII","so":"VIII","ten":"Các quy tắc tính xác suất","hk":2,"lessons":[{"id":"11-VIII-28","ten":"Bài 28. Biến cố hợp, biến cố giao, biến cố độc lập","ycc":["Nhận biết biến cố hợp, giao, xung khắc, độc lập."],"kt":["A ∪ B xảy ra khi A hoặc B xảy ra; A ∩ B (AB) xảy ra khi cả A và B xảy ra.","A, B xung khắc nếu A ∩ B = ∅.","A, B độc lập nếu việc xảy ra của biến cố này không ảnh hưởng xác suất của biến cố kia."],"d":{"t":"mc","q":"Biến cố A ∪ B xảy ra khi","o":["A không xảy ra","Không biến cố nào xảy ra","Cả A và B xảy ra","A hoặc B xảy ra"],"g":"Định nghĩa.","a":3},"ex":[{"t":"mc","q":"Hai biến cố A và B xung khắc khi","o":["P(A) = P(B)","A ∪ B = Ω","A độc lập với B","A ∩ B = ∅"],"g":"Không cùng xảy ra.","a":3},{"t":"mc","q":"Gieo xúc xắc, A: \"số chấm chẵn\", B: \"số chấm lớn hơn 3\". A ∩ B là","o":["{4; 5; 6}","{2; 4; 5; 6}","{4; 6}","{2; 4; 6}"],"g":"Vừa chẵn vừa lớn hơn 3.","a":2},{"t":"tf","q":"Gieo một đồng xu hai lần. A: \"lần 1 sấp\", B: \"lần 2 sấp\".","s":[["A và B độc lập",true],["A ∩ B = {SS}",true],["A ∪ B có 3 kết quả",true],["A và B xung khắc",false]],"g":"SS thuộc cả hai."},{"t":"sa","q":"Gieo xúc xắc, A: \"số chấm chẵn\", B: \"số chấm lớn hơn 3\". Biến cố A ∪ B có bao nhiêu kết quả?","a":"4","g":"{2; 4; 5; 6}.","r":""},{"t":"sa","q":"Gieo xúc xắc, A: \"số chấm chẵn\", B: \"số chấm lớn hơn 3\". Biến cố A ∩ B có bao nhiêu kết quả?","a":"2","g":"{4; 6}.","r":""}]},{"id":"11-VIII-29","ten":"Bài 29. Công thức cộng xác suất","ycc":["Vận dụng công thức cộng xác suất cho hai biến cố."],"kt":["P(A ∪ B) = P(A) + P(B) − P(AB).","A, B xung khắc: P(A ∪ B) = P(A) + P(B).","Biến cố đối: P(Ā) = 1 − P(A)."],"d":{"t":"mc","q":"Nếu A và B xung khắc thì P(A ∪ B) bằng","o":["P(A) − P(B)","1","P(A) + P(B)","P(A)·P(B)"],"g":"Không có phần chung.","a":2},"ex":[{"t":"mc","q":"P(A) = 0,4, P(B) = 0,3, P(AB) = 0,1. P(A ∪ B) bằng","o":["0,12","0,7","0,6","0,8"],"g":"0,4 + 0,3 − 0,1.","a":2},{"t":"mc","q":"Lớp 40 học sinh: 25 thích Toán, 20 thích Văn, 10 thích cả hai. Xác suất chọn được bạn thích ít nhất một môn là","o":["5/8","1/2","7/8","9/8"],"g":"(25 + 20 − 10)/40 = 35/40.","a":2},{"t":"tf","q":"Gieo xúc xắc. A: \"số chấm chẵn\", B: \"số chấm ≥ 5\".","s":[["P(A) = 1/2",true],["P(B) = 1/3",true],["P(AB) = 1/6",true],["P(A ∪ B) = 5/6",false]],"g":"P(A ∪ B) = 1/2 + 1/3 − 1/6 = 2/3."},{"t":"sa","q":"A và B xung khắc, P(A) = 0,5, P(B) = 0,4. Tính P(A ∪ B).","a":"0,9","g":"0,5 + 0,4.","r":""},{"t":"sa","q":"Rút ngẫu nhiên 1 lá từ bộ bài 52 lá. Tính xác suất được lá Át hoặc lá Cơ.","a":"0,31","g":"(4 + 13 − 1)/52 = 16/52.","r":"Làm tròn đến hàng phần trăm"}]},{"id":"11-VIII-30","ten":"Bài 30. Công thức nhân xác suất cho hai biến cố độc lập","ycc":["Vận dụng công thức nhân xác suất cho hai biến cố độc lập."],"kt":["A, B độc lập: P(AB) = P(A)·P(B).","Nếu A, B độc lập thì Ā và B, A và B̄, Ā và B̄ cũng độc lập.","\"Ít nhất một\" = 1 − P(cả hai đều không xảy ra)."],"d":{"t":"mc","q":"A và B độc lập thì","o":["P(AB) = P(A)·P(B)","P(A ∪ B) = 1","P(AB) = P(A) + P(B)","P(AB) = 0"],"g":"Công thức nhân.","a":0},"ex":[{"t":"mc","q":"Hai xạ thủ bắn độc lập, xác suất trúng lần lượt 0,8 và 0,7. Xác suất cả hai cùng trúng là","o":["0,75","1,5","0,94","0,56"],"g":"0,8·0,7.","a":3},{"t":"mc","q":"Hai xạ thủ bắn độc lập, xác suất trúng lần lượt 0,8 và 0,7. Xác suất có ít nhất một người bắn trúng là","o":["0,94","0,06","0,5","0,56"],"g":"1 − 0,2·0,3.","a":0},{"t":"tf","q":"Hai máy hoạt động độc lập, xác suất hỏng lần lượt 0,1 và 0,2.","s":[["Xác suất cả hai hỏng là 0,02",true],["Xác suất cả hai tốt là 0,72",true],["Xác suất đúng một máy hỏng là 0,26",true],["Xác suất ít nhất một máy hỏng là 0,3",false]],"g":"1 − 0,72 = 0,28."},{"t":"sa","q":"Gieo xúc xắc hai lần. Tính xác suất cả hai lần đều ra mặt 6.","a":"0,03","g":"1/36 ≈ 0,028.","r":"Làm tròn đến hàng phần trăm"},{"t":"sa","q":"Chọn ngẫu nhiên đáp án cho 2 câu trắc nghiệm, mỗi câu 4 phương án. Tính xác suất đúng cả 2 câu.","a":"0,06","g":"(1/4)² = 0,0625.","r":"Làm tròn đến hàng phần trăm"}]}]},{"id":"11-IX","so":"IX","ten":"Đạo hàm","hk":2,"lessons":[{"id":"11-IX-31","ten":"Bài 31. Định nghĩa và ý nghĩa của đạo hàm","ycc":["Nhận biết định nghĩa đạo hàm, ý nghĩa hình học (hệ số góc tiếp tuyến) và ý nghĩa vật lí (vận tốc tức thời)."],"kt":["f'(x₀) = lim (f(x) − f(x₀))/(x − x₀) khi x → x₀.","Tiếp tuyến tại M(x₀; y₀): y = f'(x₀)(x − x₀) + y₀.","Vận tốc tức thời v(t) = s'(t)."],"d":{"t":"mc","q":"Đạo hàm của y = x² tại x = 3 bằng","o":["6","9","3","2"],"g":"y' = 2x.","a":0},"ex":[{"t":"mc","q":"Hệ số góc tiếp tuyến của đồ thị y = x² tại điểm có hoành độ 1 là","o":["2","4","0","1"],"g":"y'(1) = 2.","a":0},{"t":"mc","q":"Nếu s(t) là quãng đường theo thời gian thì s'(t) là","o":["Vận tốc tức thời","Quãng đường trung bình","Gia tốc","Thời gian"],"g":"Ý nghĩa vật lí.","a":0},{"t":"tf","q":"Xét đồ thị y = x³ tại M(1; 1).","s":[["y'(1) = 3",true],["Tiếp tuyến tại M là y = 3x − 2",true],["Tiếp tuyến tại M đi qua gốc tọa độ",false],["Tiếp tuyến tại M có hệ số góc dương",true]],"g":"y = 3x − 2 cắt Oy tại −2."},{"t":"sa","q":"Vị trí vật s(t) = t³ − 3t² + 5 (m). Tính vận tốc tại t = 3 (m/s).","a":"9","g":"v = 3t² − 6t.","r":""},{"t":"sa","q":"Tiếp tuyến của y = x² tại điểm có hoành độ 2 cắt trục tung tại điểm có tung độ bao nhiêu?","a":"−4","g":"y = 4(x − 2) + 4 = 4x − 4.","r":""}]},{"id":"11-IX-32","ten":"Bài 32. Các quy tắc tính đạo hàm","ycc":["Tính đạo hàm của tổng, hiệu, tích, thương, hàm hợp và các hàm sơ cấp cơ bản."],"kt":["(xⁿ)' = nxⁿ⁻¹; (√x)' = 1/(2√x); (sin x)' = cos x; (cos x)' = −sin x.","(eˣ)' = eˣ; (aˣ)' = aˣ ln a; (ln x)' = 1/x.","(uv)' = u'v + uv'; (u/v)' = (u'v − uv')/v².","Hàm hợp: [f(u(x))]' = f'(u)·u'(x)."],"d":{"t":"mc","q":"Đạo hàm của y = x³ là","o":["3x","3x²","x²","3x³"],"g":"(xⁿ)' = nxⁿ⁻¹.","a":1},"ex":[{"t":"mc","q":"(sin x)' bằng","o":["−cos x","−sin x","sin x","cos x"],"g":"Công thức.","a":3},{"t":"mc","q":"Đạo hàm của y = e²ˣ là","o":["2xe²ˣ","e²ˣ/2","2e²ˣ","e²ˣ"],"g":"Hàm hợp.","a":2},{"t":"tf","q":"Cho y = x·ln x.","s":[["Tập xác định là (0; +∞)",true],["y' = ln x + 1",true],["y'(1) = 1",true],["y'(e) = 1",false]],"g":"y'(e) = 1 + 1 = 2."},{"t":"sa","q":"Cho y = x² + 3x. Tính y'(1).","a":"5","g":"y' = 2x + 3.","r":""},{"t":"sa","q":"Cho y = (2x + 1)/(x − 1). Tính y'(2).","a":"−3","g":"y' = −3/(x − 1)².","r":""}]},{"id":"11-IX-33","ten":"Bài 33. Đạo hàm cấp hai","ycc":["Nhận biết đạo hàm cấp hai; ý nghĩa cơ học (gia tốc)."],"kt":["y'' = (y')'.","Gia tốc tức thời a(t) = v'(t) = s''(t)."],"d":{"t":"mc","q":"Cho y = x³. Đạo hàm cấp hai y'' bằng","o":["x","3x²","6","6x"],"g":"y' = 3x², y'' = 6x.","a":3},"ex":[{"t":"mc","q":"Cho y = sin x. y'' bằng","o":["sin x","−sin x","−cos x","cos x"],"g":"y' = cos x.","a":1},{"t":"mc","q":"Chuyển động s(t) = t³. Gia tốc tại t = 2 là","o":["8","12","4","6"],"g":"s'' = 6t.","a":1},{"t":"tf","q":"Chuyển động s(t) = t³ − 6t² + 9t.","s":[["v(t) = 3t² − 12t + 9",true],["a(t) = 6t − 12",true],["a(2) = 0",true],["v(1) = 1",false]],"g":"v(1) = 3 − 12 + 9 = 0."},{"t":"sa","q":"Cho y = x⁴. Tính y''(1).","a":"12","g":"y'' = 12x².","r":""},{"t":"sa","q":"Chuyển động s(t) = 2t² + t (m). Tính gia tốc (m/s²).","a":"4","g":"s'' = 4.","r":""}]}]}],"12":[{"id":"12-I","so":"I","ten":"Ứng dụng đạo hàm để khảo sát và vẽ đồ thị hàm số","hk":1,"lessons":[{"id":"12-I-1","ten":"Bài 1. Tính đơn điệu và cực trị của hàm số","ycc":["Nhận biết tính đồng biến, nghịch biến dựa vào dấu của đạo hàm cấp một; nhận biết điểm cực trị, giá trị cực trị.","Lập bảng biến thiên và tìm cực trị."],"kt":["f'(x) > 0 trên K ⇒ f đồng biến trên K; f'(x) < 0 trên K ⇒ f nghịch biến trên K.","f' đổi dấu từ + sang − tại x₀: x₀ là điểm cực đại; từ − sang +: điểm cực tiểu.","Các bước: tìm tập xác định → tính f' → tìm nghiệm của f' và điểm f' không xác định → lập bảng biến thiên → kết luận."],"d":{"t":"mc","q":"Hàm số f có f'(x) > 0 với mọi x thuộc (1; 4). Khẳng định nào đúng?","o":["f đồng biến trên (1; 4)","f(1) là giá trị lớn nhất","f nghịch biến trên (1; 4)","Chưa kết luận được"],"g":"Đạo hàm dương thì hàm số đồng biến.","a":0},"ex":[{"t":"mc","q":"Hàm số y = x³ − 3x đồng biến trên khoảng nào?","o":["(1; +∞)","(−1; 1)","(−∞; 1)","(−∞; +∞)"],"g":"y' = 3x² − 3 > 0 khi |x| > 1.","a":0},{"t":"mc","q":"Hàm số y = x³ − 3x có bao nhiêu điểm cực trị?","o":["1","3","2","0"],"g":"y' đổi dấu tại x = ±1.","a":2},{"t":"tf","q":"Cho hàm số y = x³ − 3x² + 2.","s":[["y' = 3x² − 6x",true],["Hàm số nghịch biến trên (0; 2)",true],["Hàm số đạt cực đại tại x = 0 với giá trị cực đại 2",true],["Giá trị cực tiểu bằng 0",false]],"g":"y(2) = 8 − 12 + 2 = −2."},{"t":"sa","q":"Tìm giá trị cực tiểu của hàm số y = x³ − 3x² + 2.","a":"−2","g":"Cực tiểu tại x = 2.","r":""},{"t":"sa","q":"Thể tích nước trong bể V(t) = −t³ + 6t² (m³), 0 ≤ t ≤ 4 (giờ). Tại thời điểm t nào nước chảy vào bể nhanh nhất?","a":"2","g":"Tốc độ V'(t) = −3t² + 12t lớn nhất khi V''(t) = −6t + 12 = 0.","r":""}]},{"id":"12-I-2","ten":"Bài 2. Giá trị lớn nhất và giá trị nhỏ nhất của hàm số","ycc":["Tìm giá trị lớn nhất, nhỏ nhất của hàm số trên một khoảng, đoạn.","Vận dụng vào bài toán thực tế (tối ưu)."],"kt":["Trên đoạn [a; b]: tính f tại các điểm tới hạn trong (a; b) và tại a, b rồi so sánh.","Trên khoảng: dựa vào bảng biến thiên.","Bài toán tối ưu: đặt ẩn, lập hàm số, tìm điều kiện của ẩn, khảo sát để tìm giá trị lớn nhất hoặc nhỏ nhất."],"d":{"t":"mc","q":"Giá trị lớn nhất của y = −x² + 4x trên ℝ là","o":["2","0","8","4"],"g":"Đỉnh tại x = 2.","a":3},"ex":[{"t":"mc","q":"Giá trị nhỏ nhất của y = x² − 2x trên [0; 3] là","o":["−2","−1","0","3"],"g":"Tại x = 1.","a":1},{"t":"mc","q":"Giá trị lớn nhất của y = x³ − 3x trên [0; 2] là","o":["2","4","0","−2"],"g":"f(0) = 0, f(1) = −2, f(2) = 2.","a":0},{"t":"tf","q":"Xét f(x) = x + 4/x trên đoạn [1; 4].","s":[["f'(x) = 1 − 4/x²",true],["f'(x) = 0 tại x = 2",true],["Giá trị nhỏ nhất là 4",true],["Giá trị lớn nhất là 6",false]],"g":"f(1) = f(4) = 5."},{"t":"sa","q":"Từ tấm bìa vuông cạnh 12 cm, cắt bốn góc bốn hình vuông cạnh x rồi gấp thành hộp không nắp. Thể tích lớn nhất của hộp là bao nhiêu cm³?","a":"128","g":"V = x(12 − 2x)², đạt lớn nhất tại x = 2.","r":""},{"t":"sa","q":"Lợi nhuận P(x) = −x² + 40x − 300 (triệu đồng), x là số trăm sản phẩm. Lợi nhuận lớn nhất là bao nhiêu triệu đồng?","a":"100","g":"Tại x = 20.","r":""}]},{"id":"12-I-3","ten":"Bài 3. Đường tiệm cận của đồ thị hàm số","ycc":["Nhận biết đường tiệm cận đứng, tiệm cận ngang, tiệm cận xiên của đồ thị hàm số."],"kt":["x = x₀ là tiệm cận đứng nếu f(x) → ±∞ khi x → x₀⁺ hoặc x → x₀⁻.","y = y₀ là tiệm cận ngang nếu f(x) → y₀ khi x → +∞ hoặc x → −∞.","y = (ax + b)/(cx + d): tiệm cận đứng x = −d/c, tiệm cận ngang y = a/c.","Tiệm cận xiên y = ax + b nếu f(x) − (ax + b) → 0 khi x → ±∞."],"d":{"t":"mc","q":"Tiệm cận đứng của đồ thị y = (2x + 1)/(x − 1) là","o":["x = 2","x = −1","x = 1","y = 2"],"g":"Mẫu bằng 0 tại x = 1.","a":2},"ex":[{"t":"mc","q":"Tiệm cận ngang của đồ thị y = (2x + 1)/(x − 1) là","o":["y = 2","x = 1","y = −1","y = 1"],"g":"a/c = 2.","a":0},{"t":"mc","q":"Đồ thị y = 1/x có bao nhiêu đường tiệm cận (đứng và ngang)?","o":["2","3","1","0"],"g":"x = 0 và y = 0.","a":0},{"t":"tf","q":"Cho hàm số y = (x + 3)/(x − 2).","s":[["Tiệm cận đứng là x = 2",true],["Tiệm cận ngang là y = 1",true],["Đồ thị cắt trục tung tại (0; −1,5)",true],["Giao điểm hai tiệm cận là (1; 2)",false]],"g":"Giao điểm là (2; 1)."},{"t":"sa","q":"Đồ thị y = (3x − 1)/(x + 2) có tiệm cận đứng x = a và tiệm cận ngang y = b. Tính a + b.","a":"1","g":"a = −2, b = 3.","r":""},{"t":"sa","q":"Chi phí trung bình sản xuất mỗi sản phẩm C(x) = (2x + 50)/x (triệu đồng). Khi sản xuất rất nhiều, chi phí trung bình tiến về bao nhiêu triệu đồng?","a":"2","g":"Tiệm cận ngang y = 2.","r":""}]},{"id":"12-I-4","ten":"Bài 4. Khảo sát sự biến thiên và vẽ đồ thị của hàm số","ycc":["Khảo sát và vẽ đồ thị hàm số bậc ba, hàm phân thức bậc nhất trên bậc nhất, bậc hai trên bậc nhất.","Nhận biết tính đối xứng của đồ thị; dùng đồ thị biện luận số nghiệm."],"kt":["Sơ đồ: tập xác định → chiều biến thiên, cực trị, giới hạn, tiệm cận → bảng biến thiên → đồ thị.","Hàm bậc ba có tâm đối xứng tại điểm có hoành độ là nghiệm của y'' = 0.","y = (ax + b)/(cx + d) có tâm đối xứng là giao điểm hai tiệm cận.","Số nghiệm của f(x) = m bằng số giao điểm của đồ thị y = f(x) với đường thẳng y = m."],"d":{"t":"mc","q":"Đồ thị hàm số y = ax³ + bx² + cx + d với a > 0 có đặc điểm","o":["Có tiệm cận ngang","y → −∞ khi x → +∞","y → +∞ khi x → +∞","Luôn có hai cực trị"],"g":"a > 0.","a":2},"ex":[{"t":"mc","q":"Đồ thị y = x³ − 3x + 1 cắt trục tung tại điểm","o":["(0; 1)","(1; 0)","(0; 0)","(0; −3)"],"g":"x = 0.","a":0},{"t":"mc","q":"Tâm đối xứng của đồ thị y = (x + 1)/(x − 1) là","o":["(−1; 1)","(1; 1)","(1; −1)","(0; 1)"],"g":"Giao hai tiệm cận x = 1, y = 1.","a":1},{"t":"tf","q":"Cho hàm số y = −x³ + 3x.","s":[["Đồ thị đi qua gốc tọa độ",true],["Đồ thị đối xứng qua gốc tọa độ",true],["Hàm số đạt cực đại tại x = 1",true],["Đồ thị cắt trục hoành tại 2 điểm",false]],"g":"Cắt tại x = 0, ±√3."},{"t":"sa","q":"Đồ thị y = x³ − 3x cắt trục hoành tại bao nhiêu điểm?","a":"3","g":"x(x² − 3) = 0.","r":""},{"t":"sa","q":"Phương trình x³ − 3x = 3 có bao nhiêu nghiệm thực?","a":"1","g":"Cực đại 2, cực tiểu −2; đường thẳng y = 3 nằm trên giá trị cực đại.","r":""}]},{"id":"12-I-5","ten":"Bài 5. Ứng dụng đạo hàm để giải quyết một số vấn đề liên quan đến thực tiễn","ycc":["Vận dụng đạo hàm và khảo sát hàm số để giải bài toán thực tiễn: tốc độ thay đổi, tối ưu hóa."],"kt":["Đạo hàm là tốc độ thay đổi tức thời của một đại lượng.","Bài toán tối ưu: lập hàm mục tiêu, xác định miền của biến, tìm giá trị lớn nhất hoặc nhỏ nhất.","Ví dụ: lợi nhuận, chi phí, diện tích, thể tích, dân số, vận tốc."],"d":{"t":"mc","q":"Thể tích nước trong bể V(t) = −t³ + 6t² (m³), 0 ≤ t ≤ 6 (giờ). Nước trong bể tăng trong khoảng thời gian nào?","o":["2 < t < 6","0 < t < 4","4 < t < 6","0 < t < 6"],"g":"V'(t) = 3t(4 − t) > 0 khi 0 < t < 4.","a":1},"ex":[{"t":"mc","q":"Một vật ném lên có độ cao s(t) = 20t − 5t² (m). Vật đạt độ cao lớn nhất tại thời điểm","o":["t = 4","t = 20","t = 1","t = 2"],"g":"s'(t) = 20 − 10t.","a":3},{"t":"mc","q":"Doanh thu R(x) = x(100 − x). Doanh thu lớn nhất khi","o":["x = 100","x = 0","x = 50","x = 25"],"g":"R'(x) = 100 − 2x.","a":2},{"t":"tf","q":"Dân số một thị trấn N(t) = 1000 + 30t² − t³ (người), 0 ≤ t ≤ 25 (năm).","s":[["N'(t) = 60t − 3t²",true],["Dân số tăng trong khoảng (0; 20)",true],["Tốc độ tăng dân số lớn nhất tại t = 10",true],["Dân số lớn nhất tại t = 25",false]],"g":"N đạt lớn nhất tại t = 20."},{"t":"sa","q":"Dân số N(t) = 1000 + 30t² − t³ (0 ≤ t ≤ 25), dân số lớn nhất là bao nhiêu người?","a":"5000","g":"N(20) = 1000 + 12000 − 8000.","r":""},{"t":"sa","q":"Rào mảnh vườn hình chữ nhật dựa vào bức tường (không rào cạnh giáp tường) bằng 40 m lưới. Diện tích lớn nhất là bao nhiêu m²?","a":"200","g":"S = x(40 − 2x) lớn nhất tại x = 10.","r":""}]}]},{"id":"12-II","so":"II","ten":"Vectơ và hệ trục tọa độ trong không gian","hk":1,"lessons":[{"id":"12-II-6","ten":"Bài 6. Vectơ trong không gian","ycc":["Nhận biết vectơ trong không gian; thực hiện phép cộng, trừ, nhân với số, tích vô hướng.","Vận dụng vectơ để biểu diễn một số đại lượng vật lí."],"kt":["Quy tắc hình hộp ABCD.A'B'C'D': AB + AD + AA' = AC'.","G là trọng tâm tứ diện ABCD ⇔ GA + GB + GC + GD = 0.","a·b = |a|·|b|·cos(a, b); a ⊥ b ⇔ a·b = 0."],"d":{"t":"mc","q":"Cho hình hộp ABCD.A'B'C'D'. Tổng AB + AD + AA' bằng","o":["Vectơ AC'","Vectơ AC","Vectơ A'C","Vectơ BD'"],"g":"Quy tắc hình hộp.","a":0},"ex":[{"t":"mc","q":"G là trọng tâm tứ diện ABCD khi và chỉ khi","o":["AG = GD","GA = GB = GC = GD","GA + GB + GC = GD","GA + GB + GC + GD = 0"],"g":"Định nghĩa.","a":3},{"t":"mc","q":"Hình lập phương cạnh 1. Độ dài vectơ AC' là","o":["√2","1","3","√3"],"g":"Đường chéo hình lập phương.","a":3},{"t":"tf","q":"Cho hình hộp ABCD.A'B'C'D'.","s":[["Vectơ AB bằng vectơ D'C'",true],["AB + AD = AC",true],["Vectơ AA' bằng vectơ CC'",true],["|AB + AD + AA'| = AB + AD + AA' (tổng độ dài)",false]],"g":"Độ dài tổng nhỏ hơn tổng độ dài."},{"t":"sa","q":"Hình lập phương ABCD.A'B'C'D' cạnh 2. Tính vectơ AB · vectơ AC'.","a":"4","g":"AB·(AB + AD + AA') = AB² = 4.","r":""},{"t":"sa","q":"Hình lập phương cạnh 1. Tính độ dài AC'.","a":"1,73","g":"√3 ≈ 1,73.","r":"Làm tròn đến hàng phần trăm"}]},{"id":"12-II-7","ten":"Bài 7. Hệ trục tọa độ trong không gian","ycc":["Nhận biết hệ trục Oxyz, tọa độ của điểm và của vectơ."],"kt":["M(x; y; z) ⇔ OM = x·i + y·j + z·k.","Hình chiếu của M(x; y; z) lên (Oxy) là (x; y; 0); lên trục Ox là (x; 0; 0).","Điểm đối xứng của M qua O là (−x; −y; −z).","OM = √(x² + y² + z²)."],"d":{"t":"mc","q":"Trong không gian Oxyz, cho M(1; −2; 3). Tọa độ vectơ OM là","o":["(1; −2; 3)","(−1; 2; −3)","(1; 2; 3)","(3; −2; 1)"],"g":"Tọa độ vectơ OM là tọa độ điểm M.","a":0},"ex":[{"t":"mc","q":"Hình chiếu của M(1; 2; 3) lên mặt phẳng (Oxy) là","o":["(0; 0; 3)","(1; 0; 3)","(1; 2; 0)","(0; 2; 3)"],"g":"Cho z = 0.","a":2},{"t":"mc","q":"Vectơ u = 2i − 3k có tọa độ","o":["(2; 0; −3)","(2; −3; 0)","(0; 2; −3)","(2; −3)"],"g":"Hệ số của i, j, k.","a":0},{"t":"tf","q":"Cho điểm A(1; 0; 2).","s":[["A thuộc mặt phẳng (Oxz)",true],["Hình chiếu của A trên trục Ox là (1; 0; 0)",true],["OA = √5",true],["Điểm đối xứng của A qua O là (−1; 0; 2)",false]],"g":"Đối xứng qua O là (−1; 0; −2)."},{"t":"sa","q":"Tính khoảng cách từ M(3; 4; 12) đến gốc tọa độ O.","a":"13","g":"√(9 + 16 + 144).","r":""},{"t":"sa","q":"Tính khoảng cách từ M(3; 4; 5) đến trục Oz.","a":"5","g":"√(x² + y²) = √(9 + 16).","r":""}]},{"id":"12-II-8","ten":"Bài 8. Biểu thức tọa độ của các phép toán vectơ","ycc":["Tính tổng, hiệu, tích với số, tích vô hướng, độ dài, góc bằng tọa độ; tọa độ trung điểm, trọng tâm.","Vận dụng vào bài toán thực tế."],"kt":["a ± b = (a₁ ± b₁; a₂ ± b₂; a₃ ± b₃); k·a = (ka₁; ka₂; ka₃).","a·b = a₁b₁ + a₂b₂ + a₃b₃; |a| = √(a₁² + a₂² + a₃²).","cos(a, b) = a·b / (|a|·|b|).","Trung điểm I: trung bình cộng tọa độ hai điểm; trọng tâm G: trung bình cộng tọa độ ba đỉnh."],"d":{"t":"mc","q":"Vectơ a = (1; 2; 2) có độ dài bằng","o":["3","5","9","√5"],"g":"√(1 + 4 + 4).","a":0},"ex":[{"t":"mc","q":"Cho a = (1; 2; −1), b = (2; 0; 2). Góc giữa a và b là","o":["90°","60°","45°","0°"],"g":"a·b = 2 + 0 − 2 = 0.","a":0},{"t":"mc","q":"Trung điểm của AB với A(1; 2; 3), B(3; 0; −1) là","o":["(2; 2; 2)","(2; 1; 1)","(4; 2; 2)","(1; −1; −2)"],"g":"Trung bình cộng.","a":1},{"t":"tf","q":"Cho A(1; 0; 0), B(0; 2; 0), C(0; 0; 3).","s":[["Vectơ AB = (−1; 2; 0)",true],["Trọng tâm tam giác ABC là G(1/3; 2/3; 1)",true],["AB · AC = 1",true],["|AC| = √8",false]],"g":"AC = (−1; 0; 3) nên |AC| = √10."},{"t":"sa","q":"Cho A(1; 1; 1), B(4; 5; 1). Tính AB.","a":"5","g":"√(9 + 16 + 0).","r":""},{"t":"sa","q":"Một flycam bay từ gốc O đến điểm M(30; 40; 120) (đơn vị mét). Tính quãng đường thẳng OM (m).","a":"130","g":"√(900 + 1600 + 14400).","r":""}]}]},{"id":"12-III","so":"III","ten":"Các số đặc trưng đo mức độ phân tán của mẫu số liệu ghép nhóm","hk":1,"lessons":[{"id":"12-III-9","ten":"Bài 9. Khoảng biến thiên và khoảng tứ phân vị","ycc":["Tính khoảng biến thiên, khoảng tứ phân vị của mẫu số liệu ghép nhóm và giải thích ý nghĩa."],"kt":["Khoảng biến thiên R = đầu mút phải của nhóm cuối − đầu mút trái của nhóm đầu.","Q₁ = uₘ + ((n/4 − C)/nₘ)·h; Q₃ tính tương tự với 3n/4.","Khoảng tứ phân vị ΔQ = Q₃ − Q₁, đo độ phân tán của 50% số liệu ở giữa."],"d":{"t":"mc","q":"Mẫu ghép nhóm gồm các nhóm [10; 15), [15; 20), [20; 25), [25; 30) (đều có tần số dương). Khoảng biến thiên là","o":["5","20","25","15"],"g":"30 − 10.","a":1},"ex":[{"t":"mc","q":"Khoảng tứ phân vị được tính bằng","o":["Q₂ − Q₁","Giá trị lớn nhất − giá trị nhỏ nhất","Q₃ + Q₁","Q₃ − Q₁"],"g":"Định nghĩa.","a":3},{"t":"mc","q":"Khoảng tứ phân vị đo mức độ phân tán của","o":["Giá trị lớn nhất","50% số liệu ở giữa","25% số liệu đầu","Toàn bộ số liệu"],"g":"Từ Q₁ đến Q₃.","a":1},{"t":"tf","q":"Thời gian (phút) làm bài của 42 học sinh: [0; 10): 5; [10; 20): 10; [20; 30): 15; [30; 40): 12.","s":[["Cỡ mẫu n = 42",true],["Khoảng biến thiên R = 40",true],["Q₁ thuộc nhóm [10; 20)",true],["Q₃ thuộc nhóm [20; 30)",false]],"g":"3n/4 = 31,5 > 30 nên Q₃ thuộc [30; 40)."},{"t":"sa","q":"Thời gian (phút) làm bài của 42 học sinh: [0; 10): 5; [10; 20): 10; [20; 30): 15; [30; 40): 12. Tính Q₁.","a":"15,5","g":"Q₁ = 10 + (10,5 − 5)/10·10.","r":""},{"t":"sa","q":"Thời gian (phút) làm bài của 42 học sinh: [0; 10): 5; [10; 20): 10; [20; 30): 15; [30; 40): 12. Tính khoảng tứ phân vị ΔQ.","a":"15,8","g":"Q₃ = 30 + (31,5 − 30)/12·10 = 31,25; ΔQ = 15,75.","r":"Làm tròn đến hàng phần mười"}]},{"id":"12-III-10","ten":"Bài 10. Phương sai và độ lệch chuẩn","ycc":["Tính phương sai, độ lệch chuẩn của mẫu số liệu ghép nhóm và giải thích ý nghĩa."],"kt":["Phương sai: s² = [n₁(x₁ − x̄)² + … + nₖ(xₖ − x̄)²]/n.","Độ lệch chuẩn s = √(s²).","Độ lệch chuẩn càng nhỏ thì số liệu càng tập trung quanh số trung bình."],"d":{"t":"mc","q":"Độ lệch chuẩn của mẫu số liệu là","o":["Bình phương của phương sai","Hiệu Q₃ − Q₁","Số trung bình cộng","Căn bậc hai của phương sai"],"g":"s = √(s²).","a":3},"ex":[{"t":"mc","q":"Phương sai là","o":["Hiệu giá trị lớn nhất và nhỏ nhất","Trung bình cộng các giá trị","Số xuất hiện nhiều nhất","Trung bình cộng bình phương độ lệch so với số trung bình"],"g":"Định nghĩa.","a":3},{"t":"mc","q":"Hai lớp có cùng điểm trung bình 6,5; độ lệch chuẩn lớp A là 0,8, lớp B là 1,6. Kết luận đúng là","o":["Điểm lớp A đồng đều hơn","Không so sánh được","Lớp B học giỏi hơn","Điểm lớp B đồng đều hơn"],"g":"Độ lệch chuẩn nhỏ hơn.","a":0},{"t":"tf","q":"Mẫu ghép nhóm: [0; 2): 2; [2; 4): 6; [4; 6): 2.","s":[["Số trung bình bằng 3",true],["Phương sai bằng 1,6",true],["Độ lệch chuẩn xấp xỉ 1,26",true],["Độ lệch chuẩn bằng 1,6",false]],"g":"s = √1,6 ≈ 1,26."},{"t":"sa","q":"Mẫu ghép nhóm: [0; 2): 2; [2; 4): 6; [4; 6): 2. Tính phương sai.","a":"1,6","g":"(2·4 + 6·0 + 2·4)/10.","r":""},{"t":"sa","q":"Mẫu ghép nhóm: [0; 2): 2; [2; 4): 6; [4; 6): 2. Tính độ lệch chuẩn.","a":"1,26","g":"√1,6.","r":"Làm tròn đến hàng phần trăm"}]}]},{"id":"12-IV","so":"IV","ten":"Nguyên hàm và tích phân","hk":2,"lessons":[{"id":"12-IV-11","ten":"Bài 11. Nguyên hàm","ycc":["Nhận biết nguyên hàm; tính nguyên hàm của một số hàm sơ cấp; tính chất của nguyên hàm."],"kt":["F là nguyên hàm của f nếu F'(x) = f(x); ∫f(x)dx = F(x) + C.","∫xⁿdx = xⁿ⁺¹/(n + 1) + C (n ≠ −1); ∫dx/x = ln|x| + C.","∫eˣdx = eˣ + C; ∫sin x dx = −cos x + C; ∫cos x dx = sin x + C.","∫[f ± g] = ∫f ± ∫g; ∫k·f = k∫f."],"d":{"t":"mc","q":"∫2x dx bằng","o":["2x² + C","x + C","2 + C","x² + C"],"g":"(x²)' = 2x.","a":3},"ex":[{"t":"mc","q":"∫cos x dx bằng","o":["−cos x + C","cos x + C","sin x + C","−sin x + C"],"g":"(sin x)' = cos x.","a":2},{"t":"mc","q":"∫eˣ dx bằng","o":["eˣ⁺¹ + C","eˣ + C","xeˣ + C","ln x + C"],"g":"Công thức.","a":1},{"t":"tf","q":"F(x) là nguyên hàm của f(x) = 3x² + 1 thỏa F(0) = 2.","s":[["F(x) = x³ + x + C",true],["C = 2",true],["F(1) = 4",true],["F'(x) = 6x",false]],"g":"F'(x) = f(x) = 3x² + 1."},{"t":"sa","q":"Vận tốc v(t) = 3t² + 2 (m/s), quãng đường s(0) = 0. Tính quãng đường đi được sau 2 giây.","a":"12","g":"s(t) = t³ + 2t.","r":""},{"t":"sa","q":"F(x) là nguyên hàm của f(x) = 1/x trên (0; +∞) với F(1) = 0. Tính F(e²).","a":"2","g":"F(x) = ln x.","r":""}]},{"id":"12-IV-12","ten":"Bài 12. Tích phân","ycc":["Nhận biết định nghĩa, tính chất của tích phân; tính tích phân bằng nguyên hàm.","Vận dụng tích phân tính quãng đường, đại lượng tích lũy."],"kt":["∫ₐᵇ f(x)dx = F(b) − F(a).","∫ₐᵇ [f ± g] = ∫ₐᵇ f ± ∫ₐᵇ g; ∫ₐᵇ k·f = k∫ₐᵇ f; ∫ₐᵇ f = −∫ᵇₐ f.","∫ₐᶜ f = ∫ₐᵇ f + ∫ᵇᶜ f.","Quãng đường từ t = a đến t = b với vận tốc v(t) ≥ 0: s = ∫ₐᵇ v(t)dt."],"d":{"t":"mc","q":"∫₀¹ x² dx bằng","o":["1/3","1/2","2/3","1"],"g":"x³/3 từ 0 đến 1.","a":0},"ex":[{"t":"mc","q":"∫₀^π sin x dx bằng","o":["−2","0","1","2"],"g":"[−cos x] từ 0 đến π.","a":3},{"t":"mc","q":"∫₁² (2x + 1) dx bằng","o":["4","6","5","3"],"g":"[x² + x] từ 1 đến 2: 6 − 2.","a":0},{"t":"tf","q":"Biết ∫₀² f(x)dx = 5 và ∫₀² g(x)dx = 3.","s":[["∫₀² [f(x) + g(x)]dx = 8",true],["∫₀² 2f(x)dx = 10",true],["∫₂⁰ f(x)dx = −5",true],["∫₀² f(x)·g(x)dx = 15",false]],"g":"Không có tính chất tích của tích phân."},{"t":"sa","q":"Tính ∫₀² (3x² − 2x) dx.","a":"4","g":"[x³ − x²] từ 0 đến 2.","r":""},{"t":"sa","q":"Ô tô phanh với vận tốc v(t) = 20 − 5t (m/s). Từ lúc phanh đến khi dừng, xe đi được bao nhiêu mét?","a":"40","g":"Dừng tại t = 4; ∫₀⁴ (20 − 5t)dt.","r":""}]},{"id":"12-IV-13","ten":"Bài 13. Ứng dụng hình học của tích phân","ycc":["Tính diện tích hình phẳng, thể tích vật thể và khối tròn xoay bằng tích phân."],"kt":["Diện tích giới hạn bởi y = f(x), trục Ox, x = a, x = b: S = ∫ₐᵇ |f(x)|dx.","Giữa hai đồ thị: S = ∫ₐᵇ |f(x) − g(x)|dx.","Khối tròn xoay khi quay y = f(x), a ≤ x ≤ b quanh Ox: V = π∫ₐᵇ f²(x)dx."],"d":{"t":"mc","q":"Diện tích hình phẳng giới hạn bởi y = f(x), trục Ox, x = a, x = b là","o":["π∫ₐᵇ f²(x)dx","|∫ₐᵇ f²(x)dx|","∫ₐᵇ |f(x)|dx","∫ₐᵇ f(x)dx"],"g":"Công thức.","a":2},"ex":[{"t":"mc","q":"Diện tích hình phẳng giới hạn bởi y = x², trục Ox, x = 0, x = 3 là","o":["9","6","3","27"],"g":"∫₀³ x²dx = 9.","a":0},{"t":"mc","q":"Thể tích khối tròn xoay khi quay y = √x, 0 ≤ x ≤ 1 quanh Ox là","o":["π/2","2π","π/3","π"],"g":"π∫₀¹ x dx.","a":0},{"t":"tf","q":"Xét hình phẳng giới hạn bởi y = x² và y = x.","s":[["Hai đồ thị cắt nhau tại x = 0 và x = 1",true],["S = ∫₀¹ (x − x²)dx",true],["S = 1/6",true],["S = 1/3",false]],"g":"1/2 − 1/3 = 1/6."},{"t":"sa","q":"Tính diện tích hình phẳng giới hạn bởi y = 4 − x² và trục Ox.","a":"10,7","g":"∫₋₂² (4 − x²)dx = 32/3.","r":"Làm tròn đến hàng phần mười"},{"t":"sa","q":"Quay đường thẳng y = x, 0 ≤ x ≤ 3 quanh trục Ox được một khối nón. Tính thể tích khối nón.","a":"28","g":"π∫₀³ x²dx = 9π ≈ 28,27.","r":"Làm tròn đến hàng đơn vị"}]}]},{"id":"12-V","so":"V","ten":"Phương pháp tọa độ trong không gian","hk":2,"lessons":[{"id":"12-V-14","ten":"Bài 14. Phương trình mặt phẳng","ycc":["Nhận biết vectơ pháp tuyến, phương trình tổng quát của mặt phẳng; lập phương trình mặt phẳng.","Tính khoảng cách từ điểm đến mặt phẳng; điều kiện hai mặt phẳng song song, vuông góc."],"kt":["Mặt phẳng qua M(x₀; y₀; z₀) có vectơ pháp tuyến n = (A; B; C): A(x − x₀) + B(y − y₀) + C(z − z₀) = 0.","Phương trình đoạn chắn qua A(a; 0; 0), B(0; b; 0), C(0; 0; c): x/a + y/b + z/c = 1.","d(M, (P)) = |Ax₀ + By₀ + Cz₀ + D| / √(A² + B² + C²).","(P) ⊥ (Q) ⇔ n₁·n₂ = 0."],"d":{"t":"mc","q":"Mặt phẳng qua M(1; 2; 3) có vectơ pháp tuyến n = (1; 1; 1) có phương trình","o":["x + y + z − 6 = 0","x + y + z − 3 = 0","x + y + z + 6 = 0","x + 2y + 3z = 0"],"g":"1(x − 1) + 1(y − 2) + 1(z − 3) = 0.","a":0},"ex":[{"t":"mc","q":"Vectơ pháp tuyến của mặt phẳng 2x − y + 3z − 1 = 0 là","o":["(2; −1; 3)","(2; 1; 3)","(−1; 3; −1)","(2; −1; −1)"],"g":"Hệ số của x, y, z.","a":0},{"t":"mc","q":"Khoảng cách từ O đến mặt phẳng x + 2y + 2z − 6 = 0 là","o":["3","6","1","2"],"g":"6/3.","a":3},{"t":"tf","q":"Cho mặt phẳng (P): x + 2y − 2z + 3 = 0.","s":[["(P) có vectơ pháp tuyến n = (1; 2; −2)",true],["Điểm M(1; −2; 0) thuộc (P)",true],["d(O, (P)) = 1",true],["(P) song song với (Oxy)",false]],"g":"(Oxy) có pháp tuyến (0; 0; 1), không cùng phương với n."},{"t":"sa","q":"Tính khoảng cách từ A(1; 1; 1) đến mặt phẳng 2x + y − 2z + 8 = 0.","a":"3","g":"|2 + 1 − 2 + 8|/3.","r":""},{"t":"sa","q":"Mặt phẳng x/2 + y/3 + z/6 = 1 cắt ba trục tại A, B, C. Tính thể tích tứ diện OABC.","a":"6","g":"⅙·2·3·6.","r":""}]},{"id":"12-V-15","ten":"Bài 15. Phương trình đường thẳng trong không gian","ycc":["Nhận biết vectơ chỉ phương, phương trình tham số, chính tắc của đường thẳng; vị trí tương đối giữa đường thẳng và mặt phẳng."],"kt":["Đường thẳng qua M(x₀; y₀; z₀), vectơ chỉ phương u = (a; b; c): x = x₀ + at, y = y₀ + bt, z = z₀ + ct.","Chính tắc: (x − x₀)/a = (y − y₀)/b = (z − z₀)/c (a, b, c ≠ 0).","Giao điểm của d và (P): thay phương trình tham số vào phương trình (P) để tìm t."],"d":{"t":"mc","q":"Đường thẳng x = 1 + 2t, y = −t, z = 3 có vectơ chỉ phương là","o":["(2; −1; 3)","(2; −1; 0)","(1; 0; 3)","(1; −1; 0)"],"g":"Hệ số của t.","a":1},"ex":[{"t":"mc","q":"Đường thẳng qua A(1; 0; 2) có vectơ chỉ phương (1; 1; 1) có phương trình chính tắc","o":["x/1 = y/1 = z/2","(x − 1)/1 = (y − 1)/0 = (z − 2)/1","(x + 1)/1 = y/1 = (z + 2)/1","(x − 1)/1 = y/1 = (z − 2)/1"],"g":"Thay tọa độ A và vectơ chỉ phương.","a":3},{"t":"mc","q":"Điểm nào thuộc đường thẳng x = 1 + t, y = 2 − t, z = 3t?","o":["(1; 2; 3)","(2; 1; 3)","(2; 3; 3)","(0; 1; 3)"],"g":"t = 1.","a":1},{"t":"tf","q":"Cho d: x = 1 + t, y = 2t, z = 3 − t và (P): x + y + z − 4 = 0.","s":[["d có vectơ chỉ phương (1; 2; −1)",true],["A(1; 0; 3) thuộc d",true],["d cắt (P) tại A(1; 0; 3)",true],["d song song với (P)",false]],"g":"Thay vào được 2t = 0 nên d cắt (P) tại t = 0."},{"t":"sa","q":"Đường thẳng d: x = 1 + t, y = 2t, z = 3 − t cắt mặt phẳng (Oxy) tại điểm có hoành độ bằng bao nhiêu?","a":"4","g":"z = 0 ⇒ t = 3 ⇒ x = 4.","r":""},{"t":"sa","q":"Flycam bay theo đường x = 10t, y = 20t, z = 5t (mét, t giây) từ gốc O. Sau 2 giây flycam cách O bao nhiêu mét?","a":"45,8","g":"√(20² + 40² + 10²) = √2100.","r":"Làm tròn đến hàng phần mười"}]},{"id":"12-V-16","ten":"Bài 16. Công thức tính góc trong không gian","ycc":["Tính góc giữa hai đường thẳng, giữa đường thẳng và mặt phẳng, giữa hai mặt phẳng bằng tọa độ."],"kt":["Hai đường thẳng: cos φ = |u₁·u₂| / (|u₁|·|u₂|).","Đường thẳng và mặt phẳng: sin φ = |u·n| / (|u|·|n|).","Hai mặt phẳng: cos φ = |n₁·n₂| / (|n₁|·|n₂|)."],"d":{"t":"mc","q":"Côsin góc giữa hai mặt phẳng có vectơ pháp tuyến n₁, n₂ bằng","o":["n₁·n₂","|n₁| / |n₂|","|n₁ × n₂|","|n₁·n₂| / (|n₁|·|n₂|)"],"g":"Công thức.","a":3},"ex":[{"t":"mc","q":"Góc giữa mặt phẳng x − z = 0 và mặt phẳng (Oxy) là","o":["45°","60°","90°","30°"],"g":"cos = |(1; 0; −1)·(0; 0; 1)|/√2 = 1/√2.","a":0},{"t":"mc","q":"Đường thẳng có vectơ chỉ phương (1; 0; 0) và mặt phẳng có vectơ pháp tuyến (1; 0; 0) tạo góc","o":["90°","0°","60°","45°"],"g":"u cùng phương n.","a":0},{"t":"tf","q":"Cho u₁ = (1; 1; 0) và u₂ = (0; 1; 1) là vectơ chỉ phương của hai đường thẳng.","s":[["u₁·u₂ = 1",true],["|u₁| = √2",true],["Côsin góc giữa hai đường thẳng là 1/2",true],["Góc giữa hai đường thẳng là 30°",false]],"g":"cos = 1/2 nên góc 60°."},{"t":"sa","q":"Tính góc (độ) giữa đường thẳng có vectơ chỉ phương (1; 0; 1) và mặt phẳng (Oxy).","a":"45","g":"sin = 1/√2.","r":""},{"t":"sa","q":"Tính góc (độ) giữa hai mặt phẳng x + y = 0 và y + z = 0.","a":"60","g":"cos = 1/2.","r":""}]},{"id":"12-V-17","ten":"Bài 17. Phương trình mặt cầu","ycc":["Nhận biết phương trình mặt cầu; xác định tâm, bán kính; lập phương trình mặt cầu."],"kt":["Mặt cầu tâm I(a; b; c), bán kính R: (x − a)² + (y − b)² + (z − c)² = R².","x² + y² + z² − 2ax − 2by − 2cz + d = 0 là mặt cầu khi a² + b² + c² − d > 0, R = √(a² + b² + c² − d).","Mặt phẳng cắt mặt cầu theo đường tròn bán kính r = √(R² − h²), với h là khoảng cách từ tâm đến mặt phẳng."],"d":{"t":"mc","q":"Mặt cầu (x − 1)² + (y + 2)² + z² = 9 có tâm và bán kính","o":["I(1; 2; 0), R = 3","I(−1; 2; 0), R = 3","I(1; −2; 0), R = 9","I(1; −2; 0), R = 3"],"g":"Đọc từ phương trình.","a":3},"ex":[{"t":"mc","q":"Mặt cầu tâm O bán kính 2 có phương trình","o":["x + y + z = 2","x² + y² + z² = 4","x² + y² + z² = 2","(x − 2)² + y² + z² = 4"],"g":"R² = 4.","a":1},{"t":"mc","q":"Mặt cầu x² + y² + z² − 2x + 4y − 4 = 0 có tâm và bán kính","o":["I(1; −2; 0), R = 3","I(−1; 2; 0), R = 3","I(1; −2; 0), R = 9","I(2; −4; 0), R = 4"],"g":"R = √(1 + 4 + 0 + 4).","a":0},{"t":"tf","q":"Cho mặt cầu (S): (x − 1)² + y² + (z + 1)² = 4.","s":[["Tâm I(1; 0; −1)",true],["Bán kính R = 2",true],["Gốc O nằm trong mặt cầu",true],["(S) tiếp xúc với mặt phẳng (Oxy)",false]],"g":"d(I, (Oxy)) = 1 < 2 nên cắt."},{"t":"sa","q":"Tính bán kính mặt cầu tâm I(1; 2; 2) đi qua gốc O.","a":"3","g":"R = OI.","r":""},{"t":"sa","q":"Mặt phẳng z = 0 cắt mặt cầu tâm (0; 0; 3), bán kính 5 theo một đường tròn. Tính bán kính đường tròn đó.","a":"4","g":"r = √(25 − 9).","r":""}]}]},{"id":"12-VI","so":"VI","ten":"Xác suất có điều kiện","hk":2,"lessons":[{"id":"12-VI-18","ten":"Bài 18. Xác suất có điều kiện","ycc":["Nhận biết xác suất có điều kiện; tính xác suất có điều kiện; công thức nhân xác suất."],"kt":["P(A | B) = P(AB) / P(B) với P(B) > 0.","Công thức nhân: P(AB) = P(B)·P(A | B).","Có thể tính bằng cách đếm trên không gian mẫu thu hẹp (chỉ gồm các kết quả của B)."],"d":{"t":"mc","q":"Công thức xác suất có điều kiện là","o":["P(A | B) = P(A)/P(B)","P(A | B) = P(AB)/P(B)","P(A | B) = P(A) + P(B)","P(A | B) = P(A)·P(B)"],"g":"Định nghĩa.","a":1},"ex":[{"t":"mc","q":"Biết P(AB) = 0,2 và P(B) = 0,5. P(A | B) bằng","o":["0,7","0,25","0,4","0,1"],"g":"0,2/0,5.","a":2},{"t":"mc","q":"Hộp có 5 bi đỏ, 3 bi xanh. Lấy lần lượt 2 bi không hoàn lại. Biết lần 1 lấy được bi đỏ, xác suất lần 2 được bi đỏ là","o":["1/2","5/7","4/7","5/8"],"g":"Còn 4 đỏ trong 7 bi.","a":2},{"t":"tf","q":"Lớp 40 học sinh có 24 nữ; có 9 bạn nữ và 6 bạn nam đeo kính. Chọn ngẫu nhiên một bạn.","s":[["P(nữ) = 0,6",true],["P(đeo kính) = 0,375",true],["P(đeo kính | nữ) = 0,375",true],["P(nữ | đeo kính) = 0,5",false]],"g":"P(nữ | đeo kính) = 9/15 = 0,6."},{"t":"sa","q":"Lớp 40 học sinh có 24 nữ; có 9 bạn nữ và 6 bạn nam đeo kính. Chọn ngẫu nhiên một bạn đeo kính, tính xác suất bạn đó là nữ.","a":"0,6","g":"9/15.","r":""},{"t":"sa","q":"Gieo hai con xúc xắc. Biết tổng số chấm bằng 8, tính xác suất có ít nhất một con ra mặt 6.","a":"0,4","g":"Tổng 8: (2;6), (3;5), (4;4), (5;3), (6;2); có 2 trường hợp có mặt 6.","r":""}]},{"id":"12-VI-19","ten":"Bài 19. Công thức xác suất toàn phần và công thức Bayes","ycc":["Vận dụng công thức xác suất toàn phần và công thức Bayes; dùng sơ đồ hình cây."],"kt":["Xác suất toàn phần: P(A) = P(B)·P(A | B) + P(B̄)·P(A | B̄).","Bayes: P(B | A) = P(B)·P(A | B) / P(A).","Sơ đồ hình cây: nhánh thứ nhất là B, B̄; nhánh thứ hai là A, Ā; nhân xác suất theo nhánh."],"d":{"t":"mc","q":"Công thức xác suất toàn phần với hệ {B, B̄} là","o":["P(A) = P(B)P(B̄)","P(A) = P(AB)/P(B)","P(A) = P(B)P(A | B) + P(B̄)P(A | B̄)","P(A) = P(A | B) + P(A | B̄)"],"g":"Công thức.","a":2},"ex":[{"t":"mc","q":"60% sản phẩm từ nhà máy I (tỉ lệ lỗi 2%), 40% từ nhà máy II (tỉ lệ lỗi 3%). Xác suất một sản phẩm bị lỗi là","o":["0,024","0,012","0,05","0,025"],"g":"0,6·0,02 + 0,4·0,03.","a":0},{"t":"mc","q":"60% sản phẩm từ nhà máy I (tỉ lệ lỗi 2%), 40% từ nhà máy II (tỉ lệ lỗi 3%). Biết một sản phẩm bị lỗi, xác suất nó của nhà máy I là","o":["0,012","0,4","0,5","0,6"],"g":"0,012/0,024.","a":2},{"t":"tf","q":"Một bệnh có tỉ lệ mắc 10%. Xét nghiệm cho kết quả dương tính với người bệnh là 90%, với người không bệnh là 10%.","s":[["P(dương tính) = 0,18",true],["P(bệnh | dương tính) = 0,5",true],["P(âm tính | bệnh) = 0,1",true],["P(bệnh | dương tính) = 0,9",false]],"g":"Bayes: 0,09/0,18 = 0,5."},{"t":"sa","q":"70% học sinh ôn tập đều đặn, nhóm này đạt điểm từ 8 trở lên với xác suất 0,8; 30% ôn dồn, xác suất 0,4. Tính xác suất một học sinh đạt từ 8 điểm trở lên.","a":"0,68","g":"0,7·0,8 + 0,3·0,4.","r":""},{"t":"sa","q":"70% học sinh ôn tập đều đặn (đạt từ 8 điểm với xác suất 0,8), 30% ôn dồn (xác suất 0,4). Biết một học sinh đạt từ 8 điểm trở lên, tính xác suất học sinh đó ôn tập đều đặn.","a":"0,82","g":"0,56/0,68 ≈ 0,82.","r":"Làm tròn đến hàng phần trăm"}]}]}]};
window.KHKT_EXAM = [{"id":"I-1","part":1,"ten":"Nguyên hàm","lessons":["12-IV-11"],"items":[{"t":"mc","q":"Họ nguyên hàm của hàm số f(x) = 3x² là","o":["6x + C","x³/3 + C","x³ + C","3x³ + C"],"g":"∫3x²dx = x³ + C.","a":2},{"t":"mc","q":"∫(eˣ + 2x)dx bằng","o":["eˣ + x² + C","eˣ + 2 + C","xeˣ + x² + C","eˣ + 2x² + C"],"g":"∫eˣdx = eˣ + C; ∫2xdx = x² + C.","a":0},{"t":"mc","q":"Họ nguyên hàm của hàm số f(x) = cos x + 1/x trên (0; +∞) là","o":["sin x + ln x + C","−sin x − 1/x² + C","−sin x + ln x + C","sin x − 1/x² + C"],"g":"(sin x)' = cos x; (ln x)' = 1/x.","a":0}],"ref":"ĐTK 2025 câu 1; ĐCT 2025 câu 4; Đề 2026 câu 2, 8"},{"id":"I-2","part":1,"ten":"Tích phân và ứng dụng hình học","lessons":["12-IV-12","12-IV-13"],"items":[{"t":"mc","q":"Cho F(x) là một nguyên hàm của f(x) trên ℝ, F(1) = 3 và F(4) = 10. Giá trị ∫₁⁴ f(x)dx bằng","o":["13","7","30","−7"],"g":"∫₁⁴ f(x)dx = F(4) − F(1).","a":1},{"t":"mc","q":"Diện tích S của hình phẳng giới hạn bởi đồ thị y = x² − 4, trục hoành và hai đường thẳng x = 0, x = 3 là","o":["S = π∫₀³ (x² − 4)² dx","S = ∫₀³ |x² − 4| dx","S = |∫₀³ (x² − 4) dx|","S = ∫₀³ (x² − 4) dx"],"g":"Công thức diện tích dùng giá trị tuyệt đối; x² − 4 đổi dấu tại x = 2 nên không đưa dấu |…| ra ngoài tích phân được.","a":1},{"t":"mc","q":"Thể tích khối tròn xoay tạo thành khi quay hình phẳng giới hạn bởi y = √x, y = 0, x = 0, x = 4 quanh trục Ox là","o":["V = ∫₀⁴ x dx","V = π²∫₀⁴ x dx","V = π∫₀⁴ x dx","V = π∫₀⁴ √x dx"],"g":"V = π∫ₐᵇ f²(x)dx.","a":2}],"ref":"ĐTK 2025 câu 2; ĐCT 2025 câu 11; Đề 2026 câu 9"},{"id":"I-3","part":1,"ten":"Thống kê: số đặc trưng đo mức độ phân tán (lớp 12)","lessons":["12-III-9","12-III-10"],"items":[{"t":"mc","q":"Thời gian (phút) đi từ nhà đến trường của 40 học sinh: [5; 10): 6; [10; 15): 14; [15; 20): 12; [20; 25): 5; [25; 30): 3. Khoảng biến thiên của mẫu số liệu ghép nhóm là","o":["25","30","20","5"],"g":"30 − 5 = 25.","a":0},{"t":"mc","q":"Doanh số (triệu đồng/ngày) của một cửa hàng trong 30 ngày: [10; 15): 4; [15; 20): 8; [20; 25): 10; [25; 30): 6; [30; 35): 2. Tứ phân vị thứ nhất Q₁ (làm tròn đến hàng phần mười) là","o":["15,5","17,2","18,1","16,9"],"g":"n/4 = 7,5 thuộc nhóm [15; 20): Q₁ = 15 + (7,5 − 4)/8·5 ≈ 17,2.","a":1},{"t":"mc","q":"Cân nặng (kg) của 10 học sinh: [40; 45): 3; [45; 50): 4; [50; 55): 3. Độ lệch chuẩn của mẫu số liệu ghép nhóm (làm tròn đến hàng phần trăm) là","o":["15","7,50","2,74","3,87"],"g":"x̄ = 47,5; s² = (3·25 + 0 + 3·25)/10 = 15; s ≈ 3,87.","a":3}],"ref":"ĐTK 2025 câu 3; ĐCT 2025 câu 12; Đề 2026 câu 3"},{"id":"I-4","part":1,"ten":"Thống kê: số đặc trưng đo xu thế trung tâm (lớp 11)","lessons":["11-III-9"],"items":[{"t":"mc","q":"Số giờ tự học trong tuần của 50 học sinh: [0; 2): 8; [2; 4): 15; [4; 6): 17; [6; 8): 10. Số trung bình của mẫu số liệu (làm tròn đến hàng phần mười) là","o":["5,0","4,0","4,2","3,9"],"g":"(1·8 + 3·15 + 5·17 + 7·10)/50 = 4,16.","a":2},{"t":"mc","q":"Chiều cao (cm) của 45 cây giống: [20; 25): 7; [25; 30): 12; [30; 35): 15; [35; 40): 11. Nhóm chứa trung vị là","o":["[35; 40)","[30; 35)","[20; 25)","[25; 30)"],"g":"n/2 = 22,5; tần số tích lũy 7; 19; 34.","a":1}],"ref":"Đề 2026 câu 4"},{"id":"I-5","part":1,"ten":"Phương trình đường thẳng trong không gian","lessons":["12-V-15"],"items":[{"t":"mc","q":"Trong không gian Oxyz, đường thẳng d: (x − 1)/2 = (y + 3)/(−1) = (z − 5)/4 có một vectơ chỉ phương là","o":["u = (1; −3; 5)","u = (−1; 3; −5)","u = (2; 1; 4)","u = (2; −1; 4)"],"g":"Đọc các mẫu số.","a":3},{"t":"mc","q":"Trong không gian Oxyz, đường thẳng đi qua M(1; −2; 3) và có vectơ chỉ phương u = (2; 1; −1) có phương trình tham số là","o":["x = −1 + 2t, y = 2 + t, z = −3 − t","x = 1 + 2t, y = 2 + t, z = 3 − t","x = 2 + t, y = 1 − 2t, z = −1 + 3t","x = 1 + 2t, y = −2 + t, z = 3 − t"],"g":"x = x₀ + at, y = y₀ + bt, z = z₀ + ct.","a":3}],"ref":"ĐTK 2025 câu 4; ĐCT 2025 câu 5; Đề 2026 câu 7"},{"id":"I-6","part":1,"ten":"Phương trình mặt phẳng","lessons":["12-V-14"],"items":[{"t":"mc","q":"Trong không gian Oxyz, mặt phẳng (P): 2x − y + 3z − 5 = 0 có một vectơ pháp tuyến là","o":["n = (2; 1; 3)","n = (−1; 3; −5)","n = (2; −1; −5)","n = (2; −1; 3)"],"g":"Hệ số của x, y, z.","a":3},{"t":"mc","q":"Trong không gian Oxyz, mặt phẳng đi qua A(1; 0; −2) và có vectơ pháp tuyến n = (3; 2; −1) có phương trình là","o":["3x + 2y − z − 1 = 0","3x + 2y − z + 5 = 0","x − 2z − 5 = 0","3x + 2y − z − 5 = 0"],"g":"3(x − 1) + 2y − (z + 2) = 0.","a":3}],"ref":"ĐTK 2025 câu 7; ĐCT 2025 câu 7"},{"id":"I-7","part":1,"ten":"Tính đơn điệu, cực trị, giá trị lớn nhất (đọc bảng biến thiên)","lessons":["12-I-1","12-I-2"],"items":[{"t":"mc","q":"Cho hàm số y = f(x) có bảng biến thiên: trên (−∞; −1) f'(x) > 0 và f tăng từ −∞ đến 3; f'(−1) = 0; trên (−1; 1) f'(x) < 0 và f giảm từ 3 đến −1; f'(1) = 0; trên (1; +∞) f'(x) > 0 và f tăng từ −1 đến +∞. Hàm số nghịch biến trên khoảng","o":["(1; +∞)","(−∞; −1)","(−1; 1)","(−1; 3)"],"g":"f'(x) < 0 trên (−1; 1).","a":2},{"t":"mc","q":"Cho hàm số y = f(x) có bảng biến thiên: trên (−∞; −1) f'(x) > 0 và f tăng từ −∞ đến 3; f'(−1) = 0; trên (−1; 1) f'(x) < 0 và f giảm từ 3 đến −1; f'(1) = 0; trên (1; +∞) f'(x) > 0 và f tăng từ −1 đến +∞. Giá trị cực tiểu của hàm số là","o":["1","−3","3","−1"],"g":"Cực tiểu tại x = 1, giá trị −1.","a":3},{"t":"mc","q":"Hàm số y = f(x) có đạo hàm f'(x) = (x − 1)(x + 2)² với mọi x. Số điểm cực trị của hàm số là","o":["0","2","1","3"],"g":"f' chỉ đổi dấu tại x = 1; (x + 2)² không đổi dấu.","a":2}],"ref":"ĐTK 2025 câu 12; Đề 2026 câu 10"},{"id":"I-8","part":1,"ten":"Tiệm cận, đạo hàm","lessons":["12-I-3","11-IX-32"],"items":[{"t":"mc","q":"Tiệm cận đứng của đồ thị hàm số y = (2x − 1)/(x + 3) là","o":["x = 1/2","y = 2","x = −3","x = 3"],"g":"Mẫu bằng 0 tại x = −3.","a":2},{"t":"mc","q":"Tiệm cận ngang của đồ thị hàm số y = (x + 4)/(2x − 1) là","o":["y = 1","y = −4","x = 1/2","y = 1/2"],"g":"Tỉ số hệ số của x: 1/2.","a":3},{"t":"mc","q":"Đạo hàm của hàm số y = (x + 1)/(x − 2) là","o":["y' = −1/(x − 2)²","y' = 3/(x − 2)²","y' = 1/(x − 2)²","y' = −3/(x − 2)²"],"g":"((x − 2) − (x + 1))/(x − 2)².","a":3}],"ref":"ĐTK 2025 câu 5; ĐCT 2025 câu 10; Đề 2026 câu 12"},{"id":"I-9","part":1,"ten":"Phương trình, bất phương trình mũ và lôgarit","lessons":["11-VI-21"],"items":[{"t":"mc","q":"Nghiệm của phương trình 3ˣ⁻¹ = 27 là","o":["x = 3","x = 4","x = 10","x = 2"],"g":"x − 1 = 3.","a":1},{"t":"mc","q":"Tập nghiệm của bất phương trình log₂(x − 1) < 3 là","o":["(1; 9)","(−∞; 9)","(9; +∞)","(1; 7)"],"g":"0 < x − 1 < 8.","a":0},{"t":"mc","q":"Nghiệm của phương trình log₃(2x + 1) = 2 là","o":["x = 1/2","x = 9/2","x = 5","x = 4"],"g":"2x + 1 = 9.","a":3}],"ref":"ĐTK 2025 câu 6, 9; ĐCT 2025 câu 2"},{"id":"I-10","part":1,"ten":"Cấp số cộng, cấp số nhân","lessons":["11-II-6","11-II-7"],"items":[{"t":"mc","q":"Cấp số cộng (uₙ) có u₁ = 4 và công sai d = −3. Giá trị u₅ bằng","o":["−11","−8","−5","16"],"g":"u₅ = 4 + 4·(−3).","a":1},{"t":"mc","q":"Cấp số nhân (uₙ) có u₁ = 2 và công bội q = 3. Số hạng tổng quát của cấp số nhân là","o":["uₙ = 2·3ⁿ⁻¹","uₙ = 3·2ⁿ⁻¹","uₙ = 2 + 3(n − 1)","uₙ = 2·3ⁿ"],"g":"uₙ = u₁qⁿ⁻¹.","a":0}],"ref":"ĐTK 2025 câu 10; ĐCT 2025 câu 6; Đề 2026 câu 5"},{"id":"I-11","part":1,"ten":"Phương trình lượng giác cơ bản","lessons":["11-I-4"],"items":[{"t":"mc","q":"Tập nghiệm của phương trình tan x = 1 là","o":["{π/4 + k2π | k ∈ ℤ}","{π/2 + kπ | k ∈ ℤ}","{±π/4 + k2π | k ∈ ℤ}","{π/4 + kπ | k ∈ ℤ}"],"g":"tan x = tan(π/4).","a":3},{"t":"mc","q":"Nghiệm của phương trình cos x = −1 là","o":["x = kπ","x = π + k2π","x = −π/2 + k2π","x = k2π"],"g":"Trường hợp đặc biệt.","a":1}],"ref":"ĐCT 2025 câu 8; Đề 2026 câu 6"},{"id":"I-12","part":1,"ten":"Quan hệ song song, vuông góc; vectơ; thể tích","lessons":["11-VII-23","11-IV-12","12-II-6","11-VII-27"],"items":[{"t":"mc","q":"Cho hình chóp S.ABCD có đáy là hình vuông và SA ⊥ (ABCD). Đường thẳng BD vuông góc với mặt phẳng nào sau đây?","o":["(SAC)","(SCD)","(SAB)","(SAD)"],"g":"BD ⊥ AC và BD ⊥ SA.","a":0},{"t":"mc","q":"Cho hình hộp ABCD.A'B'C'D'. Đường thẳng AB song song với mặt phẳng nào sau đây?","o":["(ABCD)","(ABB'A')","(A'B'C'D')","(BCC'B')"],"g":"AB // A'B' ⊂ (A'B'C'D').","a":2},{"t":"mc","q":"Cho hình lăng trụ ABC.A'B'C'. Vectơ AB + vectơ BC' bằng","o":["Vectơ BC","Vectơ AC'","Vectơ A'C","Vectơ AC"],"g":"Quy tắc ba điểm.","a":1},{"t":"mc","q":"Khối chóp có diện tích đáy bằng 6 và chiều cao bằng 5 có thể tích bằng","o":["30","10","15","11"],"g":"V = ⅓·6·5.","a":1}],"ref":"ĐTK 2025 câu 8, 11; ĐCT 2025 câu 1, 3, 9; Đề 2026 câu 1, 11"},{"id":"II-1","part":2,"ten":"Khảo sát hàm số (đạo hàm, cực trị, giá trị lớn nhất, nhỏ nhất)","lessons":["12-I-1","12-I-2"],"items":[{"t":"tf","q":"Cho hàm số f(x) = x³ − 12x + 1.","s":[["f'(x) = 3x² − 12",true],["Phương trình f'(x) = 0 có đúng một nghiệm x = 2",false],["f(2) = −15",true],["Giá trị lớn nhất của f(x) trên đoạn [−3; 3] bằng 17",true]],"g":"f'(x) = 0 ⇔ x = ±2; f(−3) = 10, f(−2) = 17, f(2) = −15, f(3) = −8."},{"t":"tf","q":"Cho hàm số f(x) = x − 2ln x trên khoảng (0; +∞).","s":[["f'(x) = 1 − 2/x",true],["f'(x) = 0 ⇔ x = 2",true],["Hàm số nghịch biến trên khoảng (2; +∞)",false],["Giá trị nhỏ nhất của f(x) trên đoạn [1; e] bằng 2 − 2ln 2",true]],"g":"f' > 0 khi x > 2; f(1) = 1, f(2) = 2 − 2ln 2 ≈ 0,61, f(e) = e − 2 ≈ 0,72."},{"t":"tf","q":"Cho hàm số f(x) = x + 2cos x trên đoạn [0; π].","s":[["f'(x) = 1 − 2sin x",true],["Phương trình f'(x) = 0 có hai nghiệm trên [0; π]",true],["f(π/6) = π/6 + √3",true],["Giá trị nhỏ nhất của f(x) trên [0; π] bằng π − 2",false]],"g":"f'(x) = 0 ⇔ x = π/6 hoặc 5π/6; f(5π/6) = 5π/6 − √3 ≈ 0,89 < f(π) = π − 2 ≈ 1,14."}],"ref":"ĐTK 2025 câu II.1; ĐCT 2025 câu II.1; Đề 2026 câu II.2"},{"id":"II-2","part":2,"ten":"Tích phân trong bài toán thực tế","lessons":["12-IV-12"],"items":[{"t":"tf","q":"Một ô tô đang chạy với vận tốc 20 m/s thì người lái đạp phanh; từ thời điểm đó ô tô chuyển động chậm dần đều với vận tốc v(t) = 20 − 4t (m/s), t là thời gian tính bằng giây.","s":[["Ô tô dừng hẳn sau 5 giây",true],["Quãng đường ô tô đi được từ lúc đạp phanh đến khi dừng là ∫₀⁵ (20 − 4t)dt",true],["Quãng đường đó bằng 60 m",false],["Trong 2 giây cuối trước khi dừng, ô tô đi được 8 m",true]],"g":"∫₀⁵ (20 − 4t)dt = 50; ∫₃⁵ (20 − 4t)dt = 8."},{"t":"tf","q":"Người ta bơm nước vào một bể rỗng. Tốc độ bơm (m³/giờ) tại thời điểm t giờ là r(t) = −t² + 8t, với 0 ≤ t ≤ 8.","s":[["Tốc độ bơm lớn nhất tại thời điểm t = 4",true],["Tốc độ bơm lớn nhất là 16 m³/giờ",true],["Sau 3 giờ, lượng nước trong bể là 30 m³",false],["Sau 6 giờ, lượng nước trong bể nhiều hơn 70 m³",true]],"g":"Lượng nước sau T giờ là ∫₀ᵀ r(t)dt; sau 3 giờ: 27 m³; sau 6 giờ: 72 m³."},{"t":"tf","q":"Một vật chuyển động với gia tốc a(t) = 6t (m/s²), vận tốc ban đầu 2 m/s, t tính bằng giây.","s":[["Vận tốc của vật là v(t) = 3t² + 2",true],["v(2) = 14 m/s",true],["Quãng đường vật đi được trong 2 giây đầu là 12 m",true],["Quãng đường vật đi được từ t = 2 đến t = 3 là 19 m",false]],"g":"v(t) = ∫6t dt = 3t² + C, C = 2; ∫₀²(3t² + 2)dt = 12; ∫₂³(3t² + 2)dt = 21."}],"ref":"ĐTK 2025 câu II.2; ĐCT 2025 câu II.3, II.4; Đề 2026 câu II.1"},{"id":"II-3","part":2,"ten":"Xác suất có điều kiện, công thức xác suất toàn phần, Bayes","lessons":["12-VI-18","12-VI-19"],"items":[{"t":"tf","q":"Một nhà máy có hai dây chuyền. Dây chuyền I làm ra 60% sản phẩm, tỉ lệ phế phẩm 3%; dây chuyền II làm ra 40% sản phẩm, tỉ lệ phế phẩm 5%. Chọn ngẫu nhiên một sản phẩm của nhà máy.","s":[["Xác suất sản phẩm do dây chuyền I làm ra là 0,6",true],["Xác suất sản phẩm là phế phẩm, biết nó do dây chuyền II làm ra, là 0,05",true],["Xác suất sản phẩm là phế phẩm bằng 0,038",true],["Biết sản phẩm là phế phẩm, xác suất nó do dây chuyền I làm ra lớn hơn 0,5",false]],"g":"P = 0,6·0,03 + 0,4·0,05 = 0,038; P(I | phế phẩm) = 0,018/0,038 ≈ 0,47."},{"t":"tf","q":"Ở một trường, 40% học sinh tham gia câu lạc bộ Toán. Trong số học sinh tham gia, 70% đạt loại giỏi môn Toán; trong số không tham gia, 30% đạt loại giỏi. Chọn ngẫu nhiên một học sinh.","s":[["Xác suất học sinh đó không tham gia câu lạc bộ là 0,6",true],["Xác suất học sinh đó đạt loại giỏi là 0,46",true],["Biết học sinh đó đạt loại giỏi, xác suất học sinh đó tham gia câu lạc bộ xấp xỉ 0,61",true],["Xác suất học sinh đạt loại giỏi, biết học sinh đó không tham gia câu lạc bộ, là 0,18",false]],"g":"P(giỏi) = 0,28 + 0,18 = 0,46; P(tham gia | giỏi) = 0,28/0,46 ≈ 0,61; P(giỏi | không tham gia) = 0,3."},{"t":"tf","q":"Một bệnh có tỉ lệ mắc trong cộng đồng là 5%. Xét nghiệm cho kết quả dương tính ở 95% người mắc bệnh và ở 10% người không mắc bệnh. Chọn ngẫu nhiên một người đi xét nghiệm.","s":[["Xác suất kết quả dương tính là 0,1425",true],["Biết kết quả dương tính, xác suất người đó mắc bệnh xấp xỉ 0,33",true],["Biết người đó không mắc bệnh, xác suất kết quả âm tính là 0,9",true],["Biết kết quả dương tính, xác suất người đó mắc bệnh lớn hơn 0,5",false]],"g":"P(+) = 0,05·0,95 + 0,95·0,1 = 0,1425; P(bệnh | +) = 0,0475/0,1425 = 1/3."}],"ref":"ĐTK 2025 câu II.3; ĐCT 2025 câu II.2; Đề 2026 câu II.3"},{"id":"II-4","part":2,"ten":"Hình học tọa độ Oxyz trong bài toán thực tế","lessons":["12-V-15","12-V-17"],"items":[{"t":"tf","q":"Trong không gian Oxyz (đơn vị mét), một flycam xuất phát từ A(0; 0; 10) và bay thẳng đều, sau t giây ở vị trí M(3t; 4t; 10).","s":[["Sau 2 giây, flycam ở vị trí (6; 8; 10)",true],["Tốc độ của flycam là 6 m/s",false],["Đường bay có phương trình tham số x = 3t, y = 4t, z = 10",true],["Khoảng cách nhỏ nhất từ flycam đến điểm C(10; 0; 10) bằng 8 m",true]],"g":"Mỗi giây flycam dời theo vectơ (3; 4; 0) có độ dài 5 nên tốc độ 5 m/s; khoảng cách từ C đến đường bay = |AC × u|/|u| = 40/5 = 8."},{"t":"tf","q":"Trong không gian Oxyz (đơn vị km), một trạm phát sóng đặt tại I(2; 3; 1), vùng phủ sóng là khối cầu tâm I bán kính 5 km.","s":[["Vùng phủ sóng được mô tả bởi (x − 2)² + (y − 3)² + (z − 1)² ≤ 25",true],["Điểm A(5; 7; 1) nằm trên mặt cầu giới hạn vùng phủ sóng",true],["Điểm B(8; 3; 1) nằm trong vùng phủ sóng",false],["Mặt phẳng (Oxy) cắt vùng phủ sóng theo một hình tròn bán kính 2√6 km",true]],"g":"IA = 5; IB = 6 > 5; d(I, (Oxy)) = 1 nên r = √(25 − 1) = 2√6."},{"t":"tf","q":"Trong không gian Oxyz (đơn vị km), mặt đất là mặt phẳng (Oxy), đài kiểm soát đặt tại O. Một máy bay bay thẳng từ A(10; 0; 6) đến B(0; 10; 6).","s":[["Vectơ AB = (−10; 10; 0)",true],["Trong quá trình bay từ A đến B, độ cao của máy bay luôn bằng 6 km",true],["Quãng đường AB bằng 10√2 km",true],["Khoảng cách gần nhất từ máy bay đến đài kiểm soát nhỏ hơn 9 km",false]],"g":"Điểm gần O nhất trên đoạn AB là trung điểm (5; 5; 6), cách O √86 ≈ 9,27 km."}],"ref":"ĐTK 2025 câu II.4; ĐCT 2025 câu II.3; Đề 2026 câu II.4"},{"id":"III-1","part":3,"ten":"Hình học không gian: khoảng cách, thể tích","lessons":["11-VII-26","11-VII-27"],"items":[{"t":"sa","q":"Cho hình chóp S.ABCD có đáy là hình vuông cạnh 2, SA ⊥ (ABCD) và SA = 2. Tính khoảng cách giữa hai đường thẳng AB và SC.","a":"1,41","g":"AB // (SCD) nên d(AB, SC) = d(A, (SCD)) = SA·AD/√(SA² + AD²) = √2.","r":"Làm tròn đến hàng phần trăm"},{"t":"sa","q":"Cho hình lăng trụ đứng ABC.A'B'C' có đáy là tam giác vuông tại A, AB = 3, AC = 4, AA' = 6. Tính khoảng cách giữa hai đường thẳng AA' và BC.","a":"2,4","g":"Khoảng cách bằng đường cao AH của tam giác ABC: AH = 3·4/5.","r":""},{"t":"sa","q":"Tứ diện OABC có OA, OB, OC đôi một vuông góc, OA = 2, OB = 3, OC = 6. Tính khoảng cách từ O đến mặt phẳng (ABC).","a":"1,6","g":"1/d² = 1/4 + 1/9 + 1/36 = 7/18.","r":"Làm tròn đến hàng phần mười"},{"t":"sa","q":"Một kim tự tháp có dạng hình chóp tứ giác đều, cạnh đáy 230 m, chiều cao 146 m. Thể tích kim tự tháp bằng bao nhiêu nghìn mét khối?","a":"2574","g":"V = ⅓·230²·146 ≈ 2 574 467 m³.","r":"Làm tròn đến hàng đơn vị"}],"ref":"ĐTK 2025 câu III.1; ĐCT 2025 câu III.3; Đề 2026 câu III.6"},{"id":"III-2","part":3,"ten":"Ứng dụng tích phân: thể tích, diện tích trong thực tế","lessons":["12-IV-13"],"items":[{"t":"sa","q":"Một chiếc bình có dạng khối tròn xoay tạo thành khi quay hình phẳng giới hạn bởi y = √x, y = 0, x = 4 (đơn vị dm) quanh trục Ox. Tính thể tích của bình (dm³).","a":"25,1","g":"V = π∫₀⁴ x dx = 8π.","r":"Làm tròn đến hàng phần mười"},{"t":"sa","q":"Một cổng có dạng parabol, chiều cao 4 m, khoảng cách hai chân cổng 4 m. Tính diện tích mặt cổng (m²).","a":"10,7","g":"Chọn hệ trục: y = 4 − x², −2 ≤ x ≤ 2; S = ∫₋₂² (4 − x²)dx = 32/3.","r":"Làm tròn đến hàng phần mười"},{"t":"sa","q":"Mặt một hồ nước được giới hạn bởi đồ thị y = x² − 4x và trục hoành, mỗi đơn vị trên trục ứng với 10 m. Tính diện tích mặt hồ (m²).","a":"1067","g":"S = ∫₀⁴ |x² − 4x|dx = 32/3 (đơn vị²); 1 đơn vị² = 100 m².","r":"Làm tròn đến hàng đơn vị"}],"ref":"ĐTK 2025 câu III.4; ĐCT 2025 câu III.2; Đề 2026 câu III.5"},{"id":"III-3","part":3,"ten":"Bài toán tối ưu, bất phương trình trong kinh tế","lessons":["12-I-5","10-VI-17"],"items":[{"t":"sa","q":"Một doanh nghiệp bán x sản phẩm (0 < x ≤ 2000) với giá p(x) = 1000 − 0,25x (nghìn đồng/sản phẩm); chi phí sản xuất C(x) = 200x + 50 000 (nghìn đồng). Doanh nghiệp cần bán bao nhiêu sản phẩm để lợi nhuận lớn nhất?","a":"1600","g":"P(x) = −0,25x² + 800x − 50 000; P'(x) = 0 ⇔ x = 1600.","r":""},{"t":"sa","q":"Cần làm một chiếc hộp không nắp, đáy hình vuông, thể tích 32 dm³. Diện tích vật liệu ít nhất cần dùng là bao nhiêu dm²?","a":"48","g":"Đáy cạnh x, cao 32/x²: S = x² + 128/x, nhỏ nhất tại x = 4, S = 48.","r":""},{"t":"sa","q":"Lợi nhuận khi bán x sản phẩm là P(x) = −0,1x² + 60x − 5000 (nghìn đồng). Cần bán tối thiểu bao nhiêu sản phẩm để có lãi (P(x) > 0)?","a":"101","g":"P(x) > 0 ⇔ 100 < x < 500.","r":""}],"ref":"ĐTK 2025 câu III.5; ĐCT 2025 câu III.6; Đề 2026 câu III.3"},{"id":"III-4","part":3,"ten":"Hệ bất phương trình bậc nhất hai ẩn (quy hoạch tuyến tính)","lessons":["10-II-4"],"items":[{"t":"sa","q":"Một xưởng làm bàn và ghế. Mỗi chiếc bàn cần 2 giờ đóng và 1 giờ sơn, lãi 300 nghìn đồng; mỗi chiếc ghế cần 1 giờ đóng và 1 giờ sơn, lãi 200 nghìn đồng. Mỗi tuần xưởng có tối đa 100 giờ đóng và 80 giờ sơn. Tiền lãi lớn nhất mỗi tuần là bao nhiêu triệu đồng?","a":"18","g":"2x + y ≤ 100, x + y ≤ 80; các đỉnh (50; 0), (20; 60), (0; 80); lãi lớn nhất tại (20; 60): 18 000 nghìn đồng.","r":""},{"t":"sa","q":"Một hộ gia đình có 8 ha đất trồng rau A và rau B. Mỗi ha rau A cần 1 đơn vị công chăm sóc, lãi 40 triệu đồng; mỗi ha rau B cần 2 đơn vị công, lãi 60 triệu đồng. Gia đình có tối đa 12 đơn vị công. Tiền lãi lớn nhất là bao nhiêu triệu đồng?","a":"400","g":"x + y ≤ 8, x + 2y ≤ 12; các đỉnh (8; 0), (4; 4), (0; 6); lãi lớn nhất 40·4 + 60·4.","r":""},{"t":"sa","q":"Một khẩu phần cần ít nhất 6 đơn vị chất P và 8 đơn vị chất Q. Mỗi kg thực phẩm A có 1 đơn vị P, 2 đơn vị Q, giá 20 nghìn đồng; mỗi kg thực phẩm B có 3 đơn vị P, 2 đơn vị Q, giá 30 nghìn đồng. Chi phí nhỏ nhất là bao nhiêu nghìn đồng?","a":"90","g":"x + 3y ≥ 6, x + y ≥ 4; các đỉnh (6; 0), (3; 1), (0; 4); chi phí nhỏ nhất 20·3 + 30·1.","r":""}],"ref":"ĐCT 2025 câu III.4; Đề 2026 câu III.2"},{"id":"III-5","part":3,"ten":"Tổ hợp, quy tắc đếm","lessons":["10-VIII-23","10-VIII-24"],"items":[{"t":"sa","q":"Có bao nhiêu cách xếp 3 bạn nam và 3 bạn nữ thành một hàng ngang sao cho nam và nữ đứng xen kẽ?","a":"72","g":"2·3!·3!.","r":""},{"t":"sa","q":"Có bao nhiêu cách chia 6 quyển sách khác nhau cho 3 bạn, mỗi bạn 2 quyển?","a":"90","g":"C₆²·C₄²·C₂².","r":""},{"t":"sa","q":"Từ các chữ số 0, 1, 2, 3, 4, 5 lập được bao nhiêu số tự nhiên có 4 chữ số khác nhau và chia hết cho 5?","a":"108","g":"Tận cùng 0: A₅³ = 60; tận cùng 5: 4·A₄² = 48.","r":""},{"t":"sa","q":"Cho 10 điểm trên mặt phẳng, trong đó có đúng 4 điểm thẳng hàng, ngoài ra không có 3 điểm nào thẳng hàng. Có bao nhiêu tam giác có 3 đỉnh lấy từ 10 điểm đó?","a":"116","g":"C₁₀³ − C₄³.","r":""}],"ref":"ĐCT 2025 câu III.1; Đề 2026 câu III.4"},{"id":"III-6","part":3,"ten":"Xác suất (cổ điển, có điều kiện)","lessons":["10-IX-27","12-VI-18"],"items":[{"t":"sa","q":"Chọn ngẫu nhiên 3 số khác nhau từ tập {1; 2; …; 20}. Tính xác suất để 3 số đó (sắp xếp theo thứ tự tăng dần) lập thành một cấp số cộng.","a":"0,08","g":"Số bộ ba lập cấp số cộng: Σ(20 − 2d) với d = 1…9, bằng 90; P = 90/C₂₀³.","r":"Làm tròn đến hàng phần trăm"},{"t":"sa","q":"Hộp có 4 bi đỏ, 5 bi xanh và 6 bi vàng. Lấy ngẫu nhiên 4 bi. Tính xác suất 4 bi lấy ra có đủ ba màu.","a":"0,53","g":"(C₄²·5·6 + 4·C₅²·6 + 4·5·C₆²)/C₁₅⁴ = 720/1365.","r":"Làm tròn đến hàng phần trăm"},{"t":"sa","q":"Gieo hai con xúc xắc cân đối. Biết có ít nhất một con xuất hiện mặt 6 chấm, tính xác suất tổng số chấm không nhỏ hơn 10.","a":"0,45","g":"Có 11 kết quả có mặt 6; trong đó 5 kết quả có tổng ≥ 10.","r":"Làm tròn đến hàng phần trăm"}],"ref":"ĐTK 2025 câu III.6; ĐCT 2025 câu III.5; Đề 2026 câu III.1"}];
